import { ArrowBackIcon, LLMHelperBanner } from "../../../components";
import { useTradingParamsScript } from "./TradingParams.script";
import { ParamForm } from "./ParamForm";
import { PreviewPanel } from "./PreviewPanel";
import { ImportParamsModal, SubmitModal } from "../../../modals";
import { Button } from "@/components/button";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/dialog";
import { AssetTypePill } from "../AssetTypePill";
import { PreTgePill } from "../../../components/PreTgePill";
import { PLInput } from "../../../components/Input";
import { SymbolIconCropModal } from "./SymbolIconCropModal";

export function TradingParamsPanel() {
  const {
    form,
    updateField,
    errors,
    warnings,
    leverage,
    imr,
    mmr,
    fundingCap,
    fundingFloor,
    quoteTick,
    baseTick,
    baseMin,
    baseMax,
    selectedSources,
    submitting,
    onPrimarySubmitClick,
    onSubmitFromModal,
    submitModalOpen,
    setSubmitModalOpen,
    submitSymbolLabel,
    defaultListingDate,
    brokerId,
    onBack,
    onValidateFields,
    openImportModal,
    importModalOpen,
    setImportModalOpen,
    importJSON,
    copyForLLM,
    editMode,
    prettySymbol,
    effectiveListingBase,
    cexFundingParamsLoading,
    cexTickParamsLoading,
    fundingPeriodPending,
    fundingPeriodEffectiveAt,
    displayNameEditable,
    symbolContext,
    listingAssetType,
    isPretge,
    showEndPretgePhasePanel,
    endPretgeDialogOpen,
    setEndPretgeDialogOpen,
    endPretgeConfirmText,
    setEndPretgeConfirmText,
    endPretgeConfirmSymbol,
    canConfirmEndPretgePhase,
    onConfirmEndPretgePhase,
    rwaMarketSession,
    rwaMarketSessionOptions,
    rwaMarketSessionError,
    rwaMarketSessionLoading,
    hasStagedSymbolIcon,
    symbolIconDisplayUrl,
    stageSymbolIcon,
    removeSymbolIcon,
    crop,
    onSymbolIconCropConfirm,
  } = useTradingParamsScript();

  return (
    <div className="flex flex-col">
      {/* Header row: back arrow, title + description, Submit */}
      <div className="flex items-center gap-4 mb-6">
        <button
          type="button"
          onClick={onBack}
          className="shrink-0 p-0 border-0 bg-transparent cursor-pointer opacity-70 hover:opacity-100 transition-opacity text-base-contrast-98"
          aria-label="Go back"
        >
          <ArrowBackIcon className="w-6 h-6" />
        </button>
        <div className="flex-1 min-w-0 flex flex-col gap-2">
          <div className="flex items-center gap-2.5">
            <span className="text-lg font-medium text-base-contrast-98 leading-tight">
              {editMode
                ? `Edit ${prettySymbol} — Trading Parameters`
                : "Step 2: Trading Parameters"}
            </span>
            {isPretge ? (
              <PreTgePill className="shrink-0" />
            ) : (
              <AssetTypePill
                assetType={listingAssetType}
                className="shrink-0"
              />
            )}
          </div>
          <span className="text-xs font-medium text-base-contrast-50 leading-tight">
            Configure leverage, margin rate, and funding rate rules for this
            Symbol.
          </span>
        </div>
        <Button
          onClick={onPrimarySubmitClick}
          disabled={submitting}
          loading={submitting}
          className="min-w-[132px]"
        >
          {editMode ? "Save changes" : "Submit"}
        </Button>
      </div>

      <LLMHelperBanner
        onCopyForLLM={copyForLLM}
        className="mt-2 mb-10 rounded-2xl border border-base-contrast-20 px-4 py-4"
      />

      <div className="flex flex-col lg:flex-row gap-6 items-start">
        <ParamForm
          form={form}
          errors={errors}
          warnings={warnings}
          fundingPeriodPending={fundingPeriodPending}
          fundingPeriodEffectiveAt={fundingPeriodEffectiveAt}
          symbolContext={symbolContext}
          displayNameEditable={displayNameEditable}
          listingAssetType={listingAssetType}
          isPretge={isPretge}
          rwaMarketSession={rwaMarketSession}
          rwaMarketSessionOptions={rwaMarketSessionOptions}
          rwaMarketSessionError={rwaMarketSessionError}
          rwaMarketSessionLoading={rwaMarketSessionLoading}
          hasStagedSymbolIcon={hasStagedSymbolIcon}
          symbolIconDisplayUrl={symbolIconDisplayUrl}
          symbolIconLabel={effectiveListingBase}
          onStageSymbolIcon={stageSymbolIcon}
          onRemoveSymbolIcon={removeSymbolIcon}
          onFieldChange={updateField}
          onImport={openImportModal}
          onValidateFields={onValidateFields}
          footer={
            showEndPretgePhasePanel ? (
              <div className="mt-4 rounded-[20px] border border-warning/80 bg-danger/5 px-5 py-5">
                <div className="flex flex-col gap-2">
                  <span className="text-sm font-semibold text-base-contrast-98">
                    End Pre-TGE Phase
                  </span>
                  <p className="text-xs font-medium leading-5 text-base-contrast-54">
                    This will end Pre-TGE Phase and transition this listing to a
                    standard Crypto listing.{" "}
                    <span className="text-danger">
                      This action is irreversible.
                    </span>
                  </p>
                </div>
                <Button
                  type="button"
                  variant="outline"
                  color="danger"
                  rounded="lg"
                  className="mt-4 h-12 w-full text-danger hover:text-danger"
                  disabled={submitting}
                  loading={submitting}
                  onClick={() => setEndPretgeDialogOpen(true)}
                >
                  End Pre-TGE Phase
                </Button>
              </div>
            ) : null
          }
        />
        <PreviewPanel
          form={form}
          listingBaseSymbol={effectiveListingBase}
          brokerId={brokerId}
          leverage={leverage}
          imr={imr}
          mmr={mmr}
          fundingCap={fundingCap}
          fundingFloor={fundingFloor}
          quoteTick={quoteTick}
          baseTick={baseTick}
          baseMin={baseMin}
          baseMax={baseMax}
          selectedSources={selectedSources}
          cexFundingParamsLoading={cexFundingParamsLoading}
          cexTickParamsLoading={cexTickParamsLoading}
          listingAssetType={listingAssetType}
          rwaMarketSession={rwaMarketSession}
          rwaMarketSessionOptions={rwaMarketSessionOptions}
        />
      </div>

      <SubmitModal
        open={submitModalOpen}
        onOpenChange={setSubmitModalOpen}
        symbol={submitSymbolLabel}
        onConfirm={onSubmitFromModal}
        defaultListingDate={defaultListingDate}
        submitting={submitting}
      />

      <Dialog
        open={endPretgeDialogOpen}
        onOpenChange={open => {
          if (!open && !submitting) setEndPretgeDialogOpen(false);
        }}
      >
        <DialogContent className="max-w-[440px]">
          <DialogHeader>
            <DialogTitle>End Pre-TGE Phase?</DialogTitle>
          </DialogHeader>
          <DialogBody className="space-y-5">
            <div className="text-[13px] font-medium leading-[1.6] text-base-contrast-54">
              Transitioning{" "}
              <strong className="font-medium text-base-contrast-98">
                {prettySymbol}
              </strong>{" "}
              from Pre-TGE to standard Crypto:
              <br />
              &nbsp;&nbsp;• Removes Pre-TGE risk disclosure from the trader
              banner and Pre-TGE market list tab
              <br />
              &nbsp;&nbsp;• Unlocks max leverage / OI / notional caps to
              standard PML ranges
              <br />
              &nbsp;&nbsp;• Resumes funding fee from the next funding event
              <br />
              <br />
              <strong className="font-medium text-danger">
                This action is irreversible.
              </strong>{" "}
              Once ended, this listing cannot become Pre-TGE again.
            </div>
            <div className="flex flex-col gap-2">
              <span className="text-xs font-medium text-base-contrast-98">
                Type the symbol name to confirm
              </span>
              <PLInput
                value={endPretgeConfirmText}
                onChange={event => setEndPretgeConfirmText(event.target.value)}
                placeholder={endPretgeConfirmSymbol}
                className="h-10 rounded-lg border-base-contrast-12 bg-base-300 px-3 py-0 text-xs"
              />
            </div>
          </DialogBody>
          <DialogFooter className="gap-2.5">
            <Button
              type="button"
              variant="outline"
              className="h-10 flex-1 border-base-contrast-12 text-base-contrast-54 hover:border-base-contrast-20 hover:text-base-contrast-80"
              disabled={submitting}
              onClick={() => setEndPretgeDialogOpen(false)}
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant="danger"
              className="h-10 flex-1 text-primary-foreground disabled:bg-danger disabled:text-primary-foreground disabled:opacity-50"
              disabled={!canConfirmEndPretgePhase}
              loading={submitting}
              onClick={() => {
                void onConfirmEndPretgePhase();
              }}
            >
              End Pre-TGE Phase
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <ImportParamsModal
        open={importModalOpen}
        onOpenChange={setImportModalOpen}
        onChooseFile={importJSON}
      />

      <SymbolIconCropModal crop={crop} onConfirm={onSymbolIconCropConfirm} />
    </div>
  );
}
