import { Fragment } from "react";
import { cn } from "@/utils/css";

import type { SymbolDetail } from "../../../types";
import type { RwaInfoRow, RwaMarketHoliday } from "../../../services/types";
import { useRwaInfo } from "../../../services";
import { DetailRow } from "./SymbolDetailPanel.shared";
import { formatOffMarketLeverageValue } from "../../listing/trading-params/hooks/shared";

type RwaSessionOpenMode = "open" | "closed" | "fallback";

function normalizeRwaSessionStatus(
  status: string | undefined
): RwaSessionOpenMode {
  const s = status?.trim().toLowerCase();
  if (s === "open") return "open";
  if (s === "close" || s === "closed") return "closed";
  return "fallback";
}

function resolveRwaSessionOpenMode(
  row: RwaInfoRow,
  todayHoliday: RwaMarketHoliday | undefined
): RwaSessionOpenMode {
  if (todayHoliday?.type?.trim().toLowerCase() === "closed") {
    return "closed";
  }

  const normalizedStatus = normalizeRwaSessionStatus(row.status);
  if (normalizedStatus !== "fallback") return normalizedStatus;

  if (row.next_open != null && row.next_close != null) {
    const now = Date.now();
    return now >= row.next_open && now < row.next_close ? "open" : "closed";
  }
  return "fallback";
}

function getDateInTimeZone(timeZone: string | undefined): string {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone: timeZone || "UTC",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).formatToParts(new Date());
    const getPart = (type: string) =>
      parts.find(part => part.type === type)?.value;
    const year = getPart("year");
    const month = getPart("month");
    const day = getPart("day");
    if (year && month && day) return `${year}-${month}-${day}`;
  } catch {
    // Fall back to UTC when a backend timezone is missing or invalid.
  }

  return new Date().toISOString().slice(0, 10);
}

function getTodayHoliday(
  holidays: RwaMarketHoliday[] | undefined,
  timeZone: string | undefined
): RwaMarketHoliday | undefined {
  if (!holidays || holidays.length === 0) return undefined;
  const todayStr = getDateInTimeZone(timeZone);
  return holidays.find(holiday => holiday.date === todayStr);
}

function RwaSessionStatusBadge(props: { isOpen: boolean; statusText: string }) {
  const { isOpen, statusText } = props;

  return (
    <span className="inline-flex flex-wrap items-center justify-end gap-x-1">
      <span className="inline-flex items-center gap-1.5">
        <span
          className={cn(
            "size-1.5 shrink-0 rounded-full",
            isOpen ? "bg-success" : "bg-base-contrast-36"
          )}
        />
        <span className={isOpen ? "text-success" : "text-base-contrast-50"}>
          {statusText}
        </span>
      </span>
    </span>
  );
}

function RwaSessionStatusValue(props: {
  row: RwaInfoRow | undefined;
  holidays: RwaMarketHoliday[] | undefined;
  timeZone: string | undefined;
}) {
  const { row, holidays, timeZone } = props;
  const todayHoliday = getTodayHoliday(holidays, timeZone);

  if (!row) {
    if (todayHoliday?.type?.trim().toLowerCase() !== "closed") {
      return <span className="tabular-nums">—</span>;
    }

    return (
      <RwaSessionStatusBadge
        isOpen={false}
        statusText={
          todayHoliday.name ? `Closed (${todayHoliday.name})` : "Closed"
        }
      />
    );
  }

  const mode = resolveRwaSessionOpenMode(row, todayHoliday);
  if (mode === "fallback") {
    const raw = row.status?.trim();
    return <span className="tabular-nums">{raw ? raw : "—"}</span>;
  }

  const isOpen = mode === "open";
  const todayHolidayName = !isOpen ? todayHoliday?.name : undefined;
  const statusText = isOpen
    ? "Open"
    : todayHolidayName
      ? `Closed (${todayHolidayName})`
      : "Closed";

  return <RwaSessionStatusBadge isOpen={isOpen} statusText={statusText} />;
}

function deriveMarketLabel(detail: SymbolDetail): string {
  const session = detail.marketSession?.trim();
  const rwa = detail.rwaMarket;
  const name = rwa?.name?.trim();
  if (session && name) return `${session} · ${name}`;
  if (session) return session;
  if (name) return name;
  if (rwa?.market_session) return rwa.market_session;
  return "—";
}

function formatHolidayDate(dateStr: string): string {
  const d = new Date(`${dateStr}T00:00:00Z`);
  if (!Number.isFinite(d.getTime())) return dateStr;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  });
}

const DAY_RE =
  /^(Mon|Tue|Wed|Thu|Fri|Sat|Sun)(?:-(Mon|Tue|Wed|Thu|Fri|Sat|Sun))?\s*/i;

function capitalizeDay(value: string): string {
  return value.charAt(0).toUpperCase() + value.slice(1).toLowerCase();
}

function TradingHoursValue({ value }: { value: string }) {
  if (!value || value === "—") return <span className="tabular-nums">—</span>;

  const segments = value
    .split(",")
    .map(segment => segment.trim())
    .filter(Boolean);
  if (segments.length === 0) return <span className="tabular-nums">—</span>;

  const groups: Array<{ day?: string; times: string[] }> = [];
  for (const segment of segments) {
    const match = segment.match(DAY_RE);
    if (match) {
      const day =
        capitalizeDay(match[1]) +
        (match[2] ? `-${capitalizeDay(match[2])}` : "");
      const time =
        match[0].length < segment.length ? segment.slice(match[0].length) : "";
      const last = groups[groups.length - 1];
      if (last && last.day === day) {
        if (time) last.times.push(time);
      } else {
        groups.push({ day, times: time ? [time] : [] });
      }
    } else if (groups.length > 0) {
      groups[groups.length - 1].times.push(segment);
    } else {
      groups.push({ times: [segment] });
    }
  }

  if (groups.length === 0) return <span className="tabular-nums">—</span>;

  const hasDays = groups.some(group => group.day);

  return (
    <div
      className={cn(
        "tabular-nums grid gap-x-3 justify-end",
        hasDays && "grid-cols-[auto_auto]"
      )}
    >
      {groups.map((group, index) => (
        <Fragment key={index}>
          {hasDays && (
            <span
              className={cn(
                "text-xs font-medium text-right",
                group.day ? "text-base-contrast-50" : "invisible"
              )}
            >
              {group.day ?? ""}
            </span>
          )}
          <span className="text-xs font-medium text-base-contrast-98 whitespace-nowrap">
            {group.times.join(", ")}
          </span>
        </Fragment>
      ))}
    </div>
  );
}

function getNextHoliday(
  holidays: RwaMarketHoliday[] | undefined,
  timeZone: string | undefined
): string {
  if (!holidays || holidays.length === 0) return "—";
  const todayStr = getDateInTimeZone(timeZone);
  const upcoming = holidays
    .filter(holiday => holiday.date > todayStr)
    .sort((a, b) => a.date.localeCompare(b.date));
  if (upcoming.length === 0) return "—";
  const next = upcoming[0];
  const formatted = formatHolidayDate(next.date);
  return next.name ? `${formatted} (${next.name})` : formatted;
}

function normalizeSymbolKey(symbol: string | null | undefined): string {
  return symbol?.trim() ?? "";
}

function findRwaInfoRow(
  rows: RwaInfoRow[] | undefined,
  symbols: Array<string | null | undefined>
): RwaInfoRow | undefined {
  if (!rows || rows.length === 0) return undefined;
  const symbolKeys = symbols.map(normalizeSymbolKey).filter(Boolean);
  if (symbolKeys.length === 0) return undefined;
  return rows.find(row => symbolKeys.includes(normalizeSymbolKey(row.symbol)));
}

export function SymbolDetailTradingParamsPanel(props: {
  detail: SymbolDetail;
  params: SymbolDetail["params"];
  symbol?: string | null;
}) {
  const { detail, params, symbol } = props;
  const { data: rwaInfo } = useRwaInfo({ revalidateOnFocus: false });
  const perpSymbol = params.Symbol?.value ?? "";
  const rwaInfoRow = findRwaInfoRow(rwaInfo, [symbol, perpSymbol]);
  const marketLabel = deriveMarketLabel(detail);
  const tradingHours = detail.rwaMarket?.trading_hours ?? "—";
  const timezone = detail.rwaMarket?.timezone ?? "—";
  const showRwaSection = Boolean(
    detail.isRwa && (detail.marketSession || detail.rwaMarket || rwaInfoRow)
  );
  const offMarketRiskValue = formatOffMarketLeverageValue(
    params.initial_margin_ratio_off_market?.value ?? ""
  );

  return (
    <div className="bg-base-200 rounded-xl p-4 flex flex-col gap-3">
      <h3 className="text-xs font-medium text-base-contrast-98">
        Trading parameters
      </h3>
      <DetailRow label="Symbol" value={params.Symbol?.value ?? "—"} />
      <DetailRow
        label="Display name"
        value={params.display_symbol_name?.value ?? "—"}
      />
      <DetailRow label="Leverage" value={params.max_leverage?.value ?? "—"} />
      <DetailRow
        label="IMR / MMR"
        value={`${params.base_imr?.value ?? "—"} / ${
          params.base_mmr?.value ?? "—"
        }`}
      />
      <DetailRow label="Max OI" value={params.global_max_oi?.value ?? "—"} />
      <DetailRow
        label="Max notional"
        value={params.max_notional_user?.value ?? "—"}
      />
      <DetailRow label="Price range" value={params.price_range?.value ?? "—"} />
      {showRwaSection ? (
        <>
          <div className="h-px bg-base-contrast-12" />
          <div className="flex flex-col gap-2">
            <div className="text-xs font-medium text-base-contrast-98">
              Off-market risk
            </div>
            <DetailRow label="Max leverage" value={offMarketRiskValue} />
          </div>
          <div className="h-px bg-base-contrast-12" />
          <DetailRow label="Market" value={marketLabel} />
          <DetailRow
            label="Regular trading hours"
            value={<TradingHoursValue value={tradingHours} />}
          />
          <DetailRow label="Timezone" value={timezone} />
          <DetailRow
            label="Status"
            value={
              <RwaSessionStatusValue
                row={rwaInfoRow}
                holidays={detail.rwaMarket?.holidays}
                timeZone={detail.rwaMarket?.timezone}
              />
            }
          />
          <DetailRow
            label="Next holiday"
            value={getNextHoliday(
              detail.rwaMarket?.holidays,
              detail.rwaMarket?.timezone
            )}
          />
        </>
      ) : null}
    </div>
  );
}
