export function formatRelativeTimeLabel(
  isoTime: string,
  t: (key: string, options?: Record<string, unknown>) => string,
  nowMs: number = Date.now()
): string {
  const timestamp = Date.parse(isoTime);
  if (!Number.isFinite(timestamp)) return "-";

  const deltaMs = nowMs - timestamp;
  if (deltaMs < 0) return t("permissionlessListing.dashboard.justNow");

  const sec = Math.floor(deltaMs / 1000);
  if (sec < 10) return t("permissionlessListing.dashboard.justNow");
  if (sec < 60)
    return t("permissionlessListing.dashboard.secondsAgo", { count: sec });

  const min = Math.floor(sec / 60);
  if (min < 60)
    return t("permissionlessListing.dashboard.minutesAgo", { count: min });

  const hr = Math.floor(min / 60);
  if (hr < 24)
    return t("permissionlessListing.dashboard.hoursAgo", { count: hr });

  const day = Math.floor(hr / 24);
  return t("permissionlessListing.dashboard.daysAgo", { count: day });
}
