const FX_CURRENCIES = new Set([
  "AED",
  "AUD",
  "BRL",
  "CAD",
  "CHF",
  "CNH",
  "CNY",
  "EUR",
  "GBP",
  "HKD",
  "IDR",
  "INR",
  "JPY",
  "KRW",
  "MXN",
  "NZD",
  "PHP",
  "SEK",
  "SGD",
  "THB",
  "TRY",
  "USD",
  "ZAR",
]);

export function isCompactFxPair(symbol: string): boolean {
  const trimmed = symbol.trim().toUpperCase();
  if (!/^[A-Z]{6}$/.test(trimmed)) return false;
  return (
    FX_CURRENCIES.has(trimmed.slice(0, 3)) &&
    FX_CURRENCIES.has(trimmed.slice(3))
  );
}

export function formatCompactFxPair(symbol: string): string {
  const trimmed = symbol.trim().toUpperCase();
  if (isCompactFxPair(trimmed)) {
    return `${trimmed.slice(0, 3)}/${trimmed.slice(3)}`;
  }
  return symbol;
}

export function getCompactFxPairBase(symbol: string): string {
  const trimmed = symbol.trim().toUpperCase();
  return isCompactFxPair(trimmed) ? trimmed.slice(0, 3) : "";
}
