"use client";

import {
  buildFxSourceCandidateRows,
  buildIndexSourceCandidateRows,
  buildPretgeSourceCandidateRows,
  fetchExternalSourceQuote,
  isBrokerListingFxSourceItem,
  normalizeMappingType,
  normalizeSourceKey,
  sourceKeyToItemId,
} from "../../../../services";
import type {
  BrokerListingFxSourceRow,
  BrokerListingIndexSourceRow,
  BrokerListingPretgeSourceRow,
} from "../../../../services";
import { IndexSourceType, ListingAssetType } from "../../../../types";
import type {
  IndexSourceMeta,
  SourceItem,
  SymbolDetail,
} from "../../../../types";
import {
  PriceSourceWeightMode,
  getListingBaseFromSymbol,
  type SavedRowMerge,
} from "./shared";
import { formatCompactFxPair, isCompactFxPair } from "@/shared/fx";
import {
  isPretgeOracleSource,
  normalizePretgeSourceType,
} from "../../../../utils/pretge";

export function getSearchEditContext(input: {
  editMode: boolean;
  editSymbol: string | null;
  symbolDetails: Record<string, SymbolDetail>;
  normalizedBase: string;
}) {
  const listingBase =
    input.editMode && input.editSymbol
      ? getListingBaseFromSymbol(input.editSymbol)
      : "";
  const detail =
    input.editMode && input.editSymbol
      ? input.symbolDetails[input.editSymbol]
      : undefined;
  const sameListingBase = Boolean(
    listingBase && detail && input.normalizedBase === listingBase
  );

  return {
    detail,
    mergeDetail: input.editMode && sameListingBase,
  };
}

function isIndexSourceApiRow(row: unknown): row is BrokerListingIndexSourceRow {
  return (
    typeof row === "object" &&
    row !== null &&
    typeof (row as { source?: unknown }).source === "string"
  );
}

export function normalizeIndexSourceApiRows(
  rawRows: unknown
): BrokerListingIndexSourceRow[] {
  return (Array.isArray(rawRows) ? rawRows : []).filter(
    (source): source is BrokerListingIndexSourceRow =>
      isIndexSourceApiRow(source) && source.source !== "HYPERLIQUID"
  );
}

export function buildInitialSourceRows(input: {
  apiRows: BrokerListingIndexSourceRow[];
  normalizedBase: string;
  savedMap: Map<string, SavedRowMerge> | null;
}): SourceItem[] {
  return buildIndexSourceCandidateRows(input.apiRows, input.normalizedBase).map(
    row => {
      const saved = input.savedMap?.get(row.id);
      const selectedFromDetail = Boolean(saved);
      return {
        ...row,
        name: row.name,
        found: Boolean(saved) || row.found,
        sourceSymbol: saved?.sourceSymbol ?? row.sourceSymbol,
        feedId: saved?.feedId ?? row.feedId,
        multiplier: saved?.multiplier ?? row.multiplier,
        price: saved?.price ?? row.price,
        volume24h: saved?.volume24h ?? row.volume24h,
        weight: saved?.weight ?? row.weight,
        sourceId: saved?.sourceId ?? row.sourceId,
        mappingType: saved?.mappingType ?? row.mappingType,
        selected: selectedFromDetail,
        selectedFromDetail,
        // For builder-like sources, volume is not fetched, but we still keep the
        // volume cell in loading state while price is resolving to avoid flashing N/A.
        volumeLoading: true,
        priceLoading: true,
        loading: !selectedFromDetail,
      };
    }
  );
}

export function buildFxInitialSourceRows(input: {
  rows: BrokerListingFxSourceRow[];
  savedMap: Map<string, SavedRowMerge> | null;
}): SourceItem[] {
  return buildFxSourceCandidateRows(input.rows).map(row => {
    const saved = input.savedMap?.get(row.id);
    const selectedFromDetail = Boolean(saved);
    return {
      ...row,
      found: Boolean(saved) || row.found,
      sourceSymbol: saved?.sourceSymbol ?? row.sourceSymbol,
      multiplier: saved?.multiplier ?? row.multiplier,
      price: saved?.price ?? row.price,
      volume24h: saved?.volume24h ?? row.volume24h,
      weight: saved?.weight ?? row.weight,
      sourceId: saved?.sourceId ?? row.sourceId,
      mappingType: saved?.mappingType ?? row.mappingType,
      selected: selectedFromDetail || row.selected,
      selectedFromDetail,
      loading: false,
      priceLoading: false,
      volumeLoading: false,
      notFound: selectedFromDetail ? false : row.notFound,
    };
  });
}

export function buildPretgeInitialSourceRows(input: {
  rows: BrokerListingPretgeSourceRow[];
  savedMap: Map<string, SavedRowMerge> | null;
}): SourceItem[] {
  return buildPretgeSourceCandidateRows(input.rows).map(row => {
    const saved = input.savedMap?.get(row.id);
    const selectedFromDetail = Boolean(saved);
    return {
      ...row,
      found: row.found,
      sourceSymbol: saved?.sourceSymbol ?? row.sourceSymbol,
      multiplier: saved?.multiplier ?? row.multiplier,
      price: row.price,
      volume24h: saved?.volume24h ?? row.volume24h,
      weight: saved?.weight ?? row.weight,
      sourceId: saved?.sourceId ?? row.sourceId,
      selected: row.found && (selectedFromDetail || row.selected),
      selectedFromDetail: row.found && selectedFromDetail,
      loading: false,
      priceLoading: false,
      volumeLoading: false,
      notFound: row.notFound,
    };
  });
}

export function buildPretgeFallbackRowsFromDetail(input: {
  detail: SymbolDetail | undefined;
  savedMap: Map<string, SavedRowMerge> | null;
}): SourceItem[] {
  if (!input.detail) return [];

  return input.detail.indexSources
    .map(rawSource => normalizePretgeSourceType(rawSource))
    .filter(source => isPretgeOracleSource(source))
    .map(source => {
      const id = sourceKeyToItemId(source.source);
      const saved = input.savedMap?.get(id);
      const sourceSymbol = saved?.sourceSymbol ?? source.sourceSymbol;

      return {
        id,
        source: source.source,
        name: source.source,
        type: IndexSourceType.PretgeOracle,
        found: true,
        sourceSymbol,
        indexSourceSymbol: sourceSymbol,
        multiplier: saved?.multiplier ?? source.priceMultiplier ?? 1,
        price: saved?.price ?? source.latestPrice ?? 0,
        volume24h: saved?.volume24h ?? 0,
        weight: saved?.weight ?? source.weight ?? 0,
        sourceId: saved?.sourceId ?? source.sourceId,
        mappingType: saved?.mappingType ?? source.mappingType,
        selected: true,
        selectedFromDetail: true,
        loading: false,
        priceLoading: false,
        volumeLoading: false,
        notFound: false,
      };
    });
}

export function mergeSourceRowsById(input: {
  base: SourceItem[];
  next: SourceItem[];
}): SourceItem[] {
  if (input.next.length === 0) return input.base;

  const byId = new Map(input.base.map(source => [source.id, source]));
  const merged = [...input.base];

  for (const row of input.next) {
    const existing = byId.get(row.id);
    if (!existing) {
      merged.push(row);
      byId.set(row.id, row);
      continue;
    }

    const updated = {
      ...existing,
      ...row,
      selected: existing.selected || row.selected,
      selectedFromDetail: existing.selectedFromDetail || row.selectedFromDetail,
      weight: existing.weight || row.weight,
    };
    byId.set(row.id, updated);
    const idx = merged.findIndex(source => source.id === row.id);
    if (idx >= 0) merged[idx] = updated;
  }

  return merged;
}

export function buildOptimisticEditSourceRows(input: {
  catalog: IndexSourceMeta[];
  normalizedBase: string;
  savedMap: Map<string, SavedRowMerge>;
}): SourceItem[] {
  if (input.catalog.length === 0) return [];

  const usableCatalog = input.catalog.filter(
    row => normalizeSourceKey(row.source) !== "HYPERLIQUID"
  );
  const nameBySource = new Map(
    usableCatalog.map(row => [normalizeSourceKey(row.source), row.name])
  );
  const apiRows = usableCatalog.map<BrokerListingIndexSourceRow>(row => ({
    source: row.source,
    type: row.type,
    source_symbol: input.normalizedBase,
  }));

  return buildInitialSourceRows({
    apiRows,
    normalizedBase: input.normalizedBase,
    savedMap: input.savedMap,
  }).map(row => ({
    ...row,
    name: nameBySource.get(normalizeSourceKey(row.source)) ?? row.name,
  }));
}

export function getSearchWeightMode(input: {
  mergeDetail: boolean;
  preserveExistingWeights: boolean;
}) {
  return input.mergeDetail && input.preserveExistingWeights
    ? PriceSourceWeightMode.Preserve
    : PriceSourceWeightMode.Equal;
}

export function applySourcePatch(input: {
  sources: SourceItem[];
  rowId: string;
  patch: Partial<SourceItem>;
}) {
  const { sources, rowId, patch } = input;
  return sources.map(source =>
    source.id === rowId
      ? {
          ...source,
          ...patch,
          sourceSymbol:
            patch.sourceSymbol !== undefined
              ? patch.sourceSymbol
              : source.sourceSymbol,
          feedId: patch.feedId !== undefined ? patch.feedId : source.feedId,
          multiplier:
            patch.multiplier !== undefined
              ? patch.multiplier
              : source.multiplier,
          price: patch.price !== undefined ? patch.price : source.price,
          volume24h:
            patch.volume24h !== undefined ? patch.volume24h : source.volume24h,
        }
      : source
  );
}

function normalizeFxSourceSymbolForMatch(symbol: string): string {
  return symbol
    .trim()
    .toUpperCase()
    .replace(/[-_/\s]/g, "");
}

function getFxSourceRowTimestamp(row: BrokerListingFxSourceRow) {
  return typeof row.last_update === "number"
    ? row.last_update
    : row.last_update
      ? Date.parse(String(row.last_update))
      : null;
}

export function buildPythFxSourceFallbackPatch(input: {
  fxRows: BrokerListingFxSourceRow[];
  normalizedBase: string;
  sourceSymbol?: string;
}): Partial<SourceItem> | null {
  if (input.fxRows.length === 0) return null;

  const desiredSymbol =
    input.sourceSymbol?.trim() ||
    (isCompactFxPair(input.normalizedBase)
      ? formatCompactFxPair(input.normalizedBase)
      : input.normalizedBase);
  const desiredKey = normalizeFxSourceSymbolForMatch(desiredSymbol);

  const pythRows = input.fxRows.filter(
    row => normalizeSourceKey(row.source) === "PYTH"
  );
  const exact = pythRows.find(
    row => normalizeFxSourceSymbolForMatch(row.source_symbol) === desiredKey
  );

  if (!exact || !(Number(exact.price) > 0)) return null;

  return {
    found: true,
    notFound: false,
    sourceSymbol: exact.source_symbol,
    feedId: undefined,
    multiplier: 1,
    price: Number(exact.price),
    volume24h: 0,
    mappingType: normalizeMappingType(exact.mapping_type),
    latestPriceTs: getFxSourceRowTimestamp(exact),
    loading: false,
    priceLoading: false,
    volumeLoading: false,
  };
}

export async function fetchQuotePatchForSource(input: {
  row: IndexSourceMeta;
  normalizedBase: string;
  saved: SavedRowMerge | undefined;
  mergeDetail: boolean;
  listingAssetType?: ListingAssetType;
  fxRows?: BrokerListingFxSourceRow[];
}): Promise<{ rowId: string; patch: Partial<SourceItem> }> {
  const {
    row,
    normalizedBase,
    saved,
    mergeDetail,
    listingAssetType,
    fxRows = [],
  } = input;
  const rowId = sourceKeyToItemId(row.source);
  const apiSource = normalizeSourceKey(row.source);
  if (isPretgeOracleSource(row)) {
    return {
      rowId,
      patch: {
        found: true,
        notFound: false,
        multiplier: 1,
        loading: false,
        priceLoading: false,
        volumeLoading: false,
      },
    };
  }
  if (isBrokerListingFxSourceItem(row)) {
    return {
      rowId,
      patch: {
        loading: false,
        priceLoading: false,
        volumeLoading: false,
      },
    };
  }

  const quoteSymbol =
    apiSource === "PYTH" && saved?.feedId ? saved.feedId : saved?.sourceSymbol;
  const forceListedSavedRow = mergeDetail && saved !== undefined;
  const basePatch: Partial<SourceItem> = {
    loading: false,
    priceLoading: false,
    volumeLoading: false,
  };

  try {
    const quote = await fetchExternalSourceQuote({
      source: row.source,
      type: row.type,
      baseSymbol: normalizedBase,
      ...(quoteSymbol ? { sourceSymbol: quoteSymbol } : {}),
      listingAssetType,
    });
    if (!quote) {
      return {
        rowId,
        patch: basePatch,
      };
    }

    if (
      !quote.found &&
      apiSource === "PYTH" &&
      listingAssetType === ListingAssetType.Rwa
    ) {
      const fallbackPatch = buildPythFxSourceFallbackPatch({
        fxRows,
        normalizedBase,
        sourceSymbol: saved?.sourceSymbol ?? quote.sourceSymbol,
      });
      if (fallbackPatch) {
        return {
          rowId,
          patch: {
            ...basePatch,
            ...fallbackPatch,
          },
        };
      }
    }

    return {
      rowId,
      patch: {
        ...basePatch,
        found: forceListedSavedRow || quote.found,
        notFound: forceListedSavedRow ? false : !quote.found,
        sourceSymbol: forceListedSavedRow
          ? undefined
          : quote.found
            ? quote.sourceSymbol
            : "",
        feedId: quote.found ? quote.feedId : undefined,
        multiplier:
          !forceListedSavedRow && quote.found
            ? quote.suggestedMultiplier
            : undefined,
        price: quote.found ? quote.latestPrice : undefined,
        volume24h: quote.found ? quote.volume24h : undefined,
      },
    };
  } catch {
    return {
      rowId,
      patch: basePatch,
    };
  }
}
