import { useMemo } from "react";
import type { SWRConfiguration } from "swr";
import {
  type BrokerListingSymbolsQuery,
  useBrokerListingSymbols,
} from "../services";

export function useListingSymbolsData(
  params?: BrokerListingSymbolsQuery,
  options?: SWRConfiguration
) {
  const query = useBrokerListingSymbols(params, options);
  const symbolsData = useMemo(
    () => ({
      rows: query.data?.rows,
      total: query.data?.meta?.total ?? 0,
    }),
    [query.data]
  );

  return {
    ...query,
    listingSymbols: symbolsData.rows,
    listingSymbolsTotal: symbolsData.total,
    isLoadingListingSymbols: query.isLoading,
  };
}
