import { useSymbolCardView } from "./useSymbolCardView";
import { SymbolCardViewUI } from "./SymbolCardView.ui";

export interface SymbolCardViewProps {
  onCreateListing: () => void;
  onEdit?: (symbol: string) => void;
  onDelist?: (symbol: string) => void;
  onViewGateway?: () => void;
}

export function SymbolCardView({
  onCreateListing,
  onEdit,
  onDelist,
  onViewGateway,
}: SymbolCardViewProps) {
  const {
    symbols,
    isEmpty,
    isLoading,
    page,
    pageSize,
    total,
    onPageChange,
    onPageSizeChange,
  } = useSymbolCardView();

  return (
    <SymbolCardViewUI
      symbols={symbols}
      isEmpty={isEmpty}
      isLoading={isLoading}
      page={page}
      pageSize={pageSize}
      total={total}
      onCreateListing={onCreateListing}
      onEdit={onEdit}
      onDelist={onDelist}
      onViewGateway={onViewGateway}
      onPageChange={onPageChange}
      onPageSizeChange={onPageSizeChange}
    />
  );
}
