import { Link } from "react-router-dom";
import type { MouseEvent } from "react";
import { cn } from "@/utils/css";
import { StatusBadge } from "../../../components";
import { fmtUSDShort } from "../../../utils";
import { AlertLevel, ListingAssetType } from "../../../types";
import type { SymbolItem } from "../../../types";
import { AssetTypePill } from "../../listing/AssetTypePill";
import { PreTgePill } from "../../../components/PreTgePill";
import {
  DASH,
  formatIntOrDash,
  formatUsdShortOrDash,
  openInterestUsdValue,
} from "../formatters";
import { useTranslation } from "@/i18n";

type SymbolStatus = SymbolItem["status"];

export function SymbolCard({
  symbol: s,
  href,
  listedAtLabel,
  lastPrice,
  onView,
  onEdit,
  onDelist,
  onViewGateway,
}: {
  symbol: SymbolItem;
  href: string;
  listedAtLabel: string | null;
  /** Mark price from public market_info/price_changes for OI notional. */
  lastPrice: number;
  onView?: (event: MouseEvent<HTMLAnchorElement>) => void;
  onEdit?: () => void;
  onDelist?: () => void;
  onViewGateway?: () => void;
}) {
  const { t } = useTranslation();
  const isPostOnly = s.status === "POST_ONLY";
  const isRwa = Boolean(s.marketSession);

  const targetDepth = getTargetDepth(s);
  const bidPct = isPostOnly ? getDepthPct(s.depthBid, targetDepth) : 0;
  const askPct = isPostOnly ? getDepthPct(s.depthAsk, targetDepth) : 0;

  const bidQualified =
    isPostOnly && isDepthSideQualified(s.depthBid, targetDepth);
  const askQualified =
    isPostOnly && isDepthSideQualified(s.depthAsk, targetDepth);
  const {
    text: qualifyingTimerText,
    highlightSuccess: qualifyingTimerHighlight,
  } = getQualifyingTimerState(t, s, bidQualified, askQualified);

  return (
    <div
      className={cn(
        "flex flex-col h-full rounded-xl bg-base-200 p-5 transition-colors hover:bg-base-300"
      )}
    >
      <Link
        to={href}
        className={cn(
          "flex flex-col flex-1 min-h-0 text-left outline-none rounded-lg",
          "focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-base-200"
        )}
        aria-label={t("permissionlessListing.dashboard.viewSymbol", {
          symbol: s.displayName,
        })}
        onClick={onView}
        onKeyDown={e => {
          if (e.key === " ") {
            e.preventDefault();
            e.currentTarget.click();
          }
        }}
      >
        {/* Card header: title, description, status badge (+ optional Listed at) */}
        <div className="flex justify-between items-start gap-3 mb-4">
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2.5 min-w-0">
              <div className="text-xs font-semibold text-base-contrast-98 truncate min-w-0">
                {s.displayName}
              </div>
              {s.isPretge ? (
                <PreTgePill className="shrink-0" />
              ) : (
                <AssetTypePill
                  assetType={
                    isRwa ? ListingAssetType.Rwa : ListingAssetType.Crypto
                  }
                  className="shrink-0"
                />
              )}
            </div>
            <div className="text-3xs text-base-contrast-50 mt-1 truncate">
              {s.symbol}
            </div>
          </div>
          <div className="flex items-center gap-2 shrink-0 flex-wrap justify-end">
            <StatusBadge
              status={s.status}
              depthPct={
                isPostOnly ? Math.round((bidPct + askPct) / 2) : undefined
              }
            />
          </div>
        </div>

        {/* Card content: Processing / POST_ONLY depth / metrics grid */}
        {renderCardContent({
          symbol: s,
          listedAtLabel,
          lastPrice,
          targetDepth,
          bidPct,
          askPct,
          bidQualified,
          askQualified,
          qualifyingTimerText,
          qualifyingTimerHighlight,
          t,
          onViewGateway,
        })}
      </Link>

      {/* Card footer: Edit, Delist, View */}
      <CardFooter
        status={s.status}
        href={href}
        onView={onView}
        onEdit={onEdit}
        onDelist={onDelist}
        t={t}
      />
    </div>
  );
}

function renderCardContent(args: {
  symbol: SymbolItem;
  listedAtLabel: string | null;
  lastPrice: number;
  targetDepth: number;
  bidPct: number;
  askPct: number;
  bidQualified: boolean;
  askQualified: boolean;
  qualifyingTimerText: string;
  qualifyingTimerHighlight: boolean;
  t: ReturnType<typeof useTranslation>["t"];
  onViewGateway?: () => void;
}) {
  const {
    symbol: s,
    listedAtLabel,
    lastPrice,
    targetDepth,
    bidPct,
    askPct,
    bidQualified,
    askQualified,
    qualifyingTimerText,
    qualifyingTimerHighlight,
    t,
    onViewGateway,
  } = args;

  switch (s.status) {
    case "NEW":
    case "PENDING":
      return <NewStatusCardContent listedAtLabel={listedAtLabel} t={t} />;
    case "POST_ONLY":
      return (
        <PostOnlyStatusCardContent
          symbol={s}
          targetDepth={targetDepth}
          bidPct={bidPct}
          askPct={askPct}
          bidQualified={bidQualified}
          askQualified={askQualified}
          qualifyingTimerText={qualifyingTimerText}
          qualifyingTimerHighlight={qualifyingTimerHighlight}
          listedAtLabel={listedAtLabel}
          t={t}
          onViewGateway={onViewGateway}
        />
      );
    case "ACTIVE":
    case "REDUCE_ONLY":
    case "DELISTING":
    case "DELISTED":
      return <CardContentMetrics symbol={s} lastPrice={lastPrice} t={t} />;
    default:
      return assertNever(s.status);
  }
}

function NewStatusCardContent({
  listedAtLabel,
  t,
}: {
  listedAtLabel: string | null;
  t: ReturnType<typeof useTranslation>["t"];
}) {
  return (
    <div className="flex flex-col items-center justify-center min-h-[120px] gap-3 flex-1">
      <span
        className="inline-block w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin"
        aria-hidden
      />
      <span className="text-xs font-medium text-base-contrast-50">
        {t("permissionlessListing.dashboard.processing")}
      </span>
      {listedAtLabel && (
        <span className="text-3xs text-base-contrast-50">
          {t("permissionlessListing.dashboard.listedAt", {
            time: listedAtLabel,
          })}
        </span>
      )}
    </div>
  );
}

function PostOnlyStatusCardContent({
  symbol: s,
  targetDepth,
  bidPct,
  askPct,
  bidQualified,
  askQualified,
  qualifyingTimerText,
  qualifyingTimerHighlight,
  listedAtLabel,
  t,
  onViewGateway,
}: {
  symbol: SymbolItem;
  targetDepth: number;
  bidPct: number;
  askPct: number;
  bidQualified: boolean;
  askQualified: boolean;
  qualifyingTimerText: string;
  qualifyingTimerHighlight: boolean;
  listedAtLabel: string | null;
  t: ReturnType<typeof useTranslation>["t"];
  onViewGateway?: () => void;
}) {
  return (
    <div className="flex flex-col gap-2.5 min-h-[120px] justify-center flex-1">
      <div className="text-3xs text-base-contrast-98">
        {t("permissionlessListing.dashboard.depthTarget", {
          target: fmtUSDShort(targetDepth),
        })}
      </div>
      <div className="flex items-center gap-2 text-3xs flex-wrap">
        <span className="shrink-0 text-base-contrast-50">
          {t("permissionlessListing.dashboard.bidDepth")}
        </span>
        <div className="flex-1 min-w-0 h-1.5 rounded-full bg-base-contrast-8 overflow-hidden max-w-[120px]">
          <div
            className={cn(
              "h-full rounded-full transition-all",
              bidQualified ? "bg-success" : "bg-warning"
            )}
            style={{ width: `${bidPct}%` }}
          />
        </div>
        <span className="shrink-0 whitespace-nowrap text-base-contrast-98">
          {formatUsdShortOrDash(s.depthBid)} / {fmtUSDShort(targetDepth)}{" "}
          {bidPct}%
        </span>
      </div>
      <div className="flex items-center gap-2 text-3xs flex-wrap">
        <span className="shrink-0 text-base-contrast-50">
          {t("permissionlessListing.dashboard.askDepth")}
        </span>
        <div className="flex-1 min-w-0 h-1.5 rounded-full bg-base-contrast-8 overflow-hidden max-w-[120px]">
          <div
            className={cn(
              "h-full rounded-full transition-all",
              askQualified ? "bg-success" : "bg-warning"
            )}
            style={{ width: `${askPct}%` }}
          />
        </div>
        <span className="shrink-0 whitespace-nowrap text-base-contrast-98">
          {formatUsdShortOrDash(s.depthAsk)} / {fmtUSDShort(targetDepth)}{" "}
          {askPct}%
        </span>
      </div>
      <div className="text-3xs text-base-contrast-50">
        {t("permissionlessListing.dashboard.qualifyingTimer")}:{" "}
        <span
          className={
            qualifyingTimerHighlight ? "text-success" : "text-base-contrast-50"
          }
        >
          {qualifyingTimerText}
        </span>
      </div>
      {onViewGateway && <VipGatewayBanner onClick={onViewGateway} />}
      {listedAtLabel && (
        <div className="text-3xs text-base-contrast-50 mt-2">
          {t("permissionlessListing.dashboard.listedAt", {
            time: listedAtLabel,
          })}
        </div>
      )}
    </div>
  );
}

function CardContentMetrics({
  symbol: s,
  lastPrice,
  t,
}: {
  symbol: SymbolItem;
  lastPrice: number;
  t: ReturnType<typeof useTranslation>["t"];
}) {
  return (
    <div className="grid grid-cols-2 gap-x-4 gap-y-3 mb-4 flex-1">
      <MetricCell
        label={t("permissionlessListing.dashboard.metricVolume24h")}
        value={formatUsdShortOrDash(s.vol)}
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricTradingFee24h")}
        value={formatUsdShortOrDash(s.feeRevenue)}
        valueClassName="text-success"
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricLiquidations24h")}
        value={formatIntOrDash(s.liqCount)}
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricLiquidationFee24h")}
        value={formatUsdShortOrDash(s.liqRevenue)}
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricOpenInterest")}
        value={formatUsdShortOrDash(
          openInterestUsdValue(s.openInterest, lastPrice)
        )}
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricDepth")}
        value={formatDepthValue(t, { bid: s.depthBid, ask: s.depthAsk })}
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricIndexSource")}
        value={s.sources != null ? String(s.sources) : DASH}
      />
      <MetricCell
        label={t("permissionlessListing.dashboard.metricAlert")}
        value={formatAlertLabel(t, s.alertLevel)}
        valueClassName={cn(
          !s.alertLevel && "text-base-contrast-50",
          s.alertLevel === AlertLevel.Normal && "text-success",
          s.alertLevel === AlertLevel.Warning && "text-warning",
          s.alertLevel === AlertLevel.Limit && "text-danger"
        )}
      />
    </div>
  );
}

function CardFooter({
  status,
  href,
  onView,
  onEdit,
  onDelist,
  t,
}: {
  status: SymbolStatus;
  href: string;
  onView?: (event: MouseEvent<HTMLAnchorElement>) => void;
  onEdit?: () => void;
  onDelist?: () => void;
  t: ReturnType<typeof useTranslation>["t"];
}) {
  const canModify = canModifyStatus(status);

  return (
    <div
      className="flex justify-between items-center pt-3 border-t border-base-contrast-8 mt-auto"
      data-card-action
    >
      <div className="flex gap-2">
        {canModify && onEdit && (
          <button
            type="button"
            onClick={e => {
              e.stopPropagation();
              onEdit();
            }}
            className="text-xs font-medium text-primary-light cursor-pointer hover:opacity-90 focus:outline-none focus-visible:ring-2 focus-visible:ring-primary rounded"
          >
            {t("permissionlessListing.dashboard.edit")}
          </button>
        )}
        {canModify && onDelist && (
          <button
            type="button"
            onClick={e => {
              e.stopPropagation();
              onDelist();
            }}
            className="text-xs font-medium text-primary-light cursor-pointer hover:opacity-90 focus:outline-none focus-visible:ring-2 focus-visible:ring-primary rounded"
          >
            {t("permissionlessListing.dashboard.delist")}
          </button>
        )}
      </div>
      <Link
        to={href}
        onClick={onView}
        className="text-3xs font-medium text-base-contrast-50 hover:text-base-contrast-98 focus:outline-none focus-visible:ring-2 focus-visible:ring-primary rounded"
      >
        {t("permissionlessListing.dashboard.viewArrow")}
      </Link>
    </div>
  );
}

function MetricCell({
  label,
  value,
  valueClassName,
}: {
  label: string;
  value: string;
  valueClassName?: string;
}) {
  return (
    <div className="min-h-10">
      <div className="text-3xs text-base-contrast-50 mb-1">{label}</div>
      <div
        className={cn(
          "text-xs font-medium text-base-contrast-98 min-h-[40px]",
          valueClassName
        )}
      >
        {value}
      </div>
    </div>
  );
}

function formatDepthValue(
  t: ReturnType<typeof useTranslation>["t"],
  args: { bid: number | null | undefined; ask: number | null | undefined }
): string {
  const { bid, ask } = args;
  if (bid == null && ask == null) return DASH;

  const fmtK = (n: number | null | undefined) =>
    n == null || Number.isNaN(n) ? DASH : `$${(n / 1000).toFixed(1)}K`;

  return t("permissionlessListing.dashboard.depthBidAsk", {
    bid: fmtK(bid),
    ask: fmtK(ask),
  });
}

function formatAlertLabel(
  t: ReturnType<typeof useTranslation>["t"],
  level: AlertLevel | null | undefined
): string {
  if (!level) return DASH;
  switch (level) {
    case AlertLevel.Normal:
      return t("permissionlessListing.dashboard.alertNormal");
    case AlertLevel.Warning:
      return t("permissionlessListing.dashboard.alertWarning");
    case AlertLevel.Limit:
      return t("permissionlessListing.dashboard.alertLimit");
    default:
      return DASH;
  }
}

function assertNever(x: never): never {
  throw new Error(`Unexpected value: ${String(x)}`);
}

function canModifyStatus(status: SymbolStatus): boolean {
  switch (status) {
    case "NEW":
    case "PENDING":
    case "POST_ONLY":
    case "ACTIVE":
      return true;
    case "REDUCE_ONLY":
    case "DELISTING":
    case "DELISTED":
      return false;
    default:
      return assertNever(status);
  }
}

function getTargetDepth(s: SymbolItem): number {
  return s.targetDepth ?? 100000;
}

function getDepthPct(
  currentDepth: number | null | undefined,
  targetDepth: number
): number {
  return Math.min(100, Math.round(((currentDepth ?? 0) / targetDepth) * 100));
}

function isDepthSideQualified(
  depth: number | null | undefined,
  targetDepth: number
): boolean {
  return (depth ?? 0) >= targetDepth;
}

function formatQualifyingElapsed(elapsedSec: number): string {
  const suffix = " / 10m";
  if (elapsedSec < 60) {
    return `${elapsedSec}s${suffix}`;
  }
  const totalMins = Math.floor(elapsedSec / 60);
  const secs = elapsedSec % 60;
  if (elapsedSec < 3600) {
    return `${totalMins}m ${secs}s${suffix}`;
  }
  const hours = Math.floor(elapsedSec / 3600);
  const remAfterH = elapsedSec % 3600;
  const minsInHour = Math.floor(remAfterH / 60);
  if (elapsedSec < 86400) {
    if (minsInHour > 0) {
      return `${hours}h ${minsInHour}m${suffix}`;
    }
    return `${hours}h${suffix}`;
  }
  const days = Math.floor(elapsedSec / 86400);
  const remAfterD = elapsedSec % 86400;
  const h = Math.floor(remAfterD / 3600);
  const remAfterH2 = remAfterD % 3600;
  const m = Math.floor(remAfterH2 / 60);
  const parts: string[] = [];
  if (days > 0) parts.push(`${days}d`);
  if (h > 0) parts.push(`${h}h`);
  if (m > 0) parts.push(`${m}m`);
  if (parts.length === 0) {
    return `0m${suffix}`;
  }
  return `${parts.join(" ")}${suffix}`;
}

function getQualifyingTimerState(
  t: ReturnType<typeof useTranslation>["t"],
  s: SymbolItem,
  bidQualified: boolean,
  askQualified: boolean
): { text: string; highlightSuccess: boolean } {
  if (!bidQualified && !askQualified) {
    return {
      text: t("permissionlessListing.dashboard.bothSidesNotQualifying"),
      highlightSuccess: false,
    };
  }
  if (bidQualified && !askQualified) {
    return {
      text: t("permissionlessListing.dashboard.askSideIneligible"),
      highlightSuccess: false,
    };
  }
  if (!bidQualified && askQualified) {
    return {
      text: t("permissionlessListing.dashboard.bidSideIneligible"),
      highlightSuccess: false,
    };
  }

  if (!s.depthQualifyingSince) {
    return { text: "-", highlightSuccess: false };
  }
  const start = new Date(s.depthQualifyingSince).getTime();
  const now = Date.now();
  if (Number.isNaN(start) || now <= start) {
    return { text: "-", highlightSuccess: false };
  }
  const elapsedSec = Math.floor((now - start) / 1000);
  return {
    text: formatQualifyingElapsed(elapsedSec),
    highlightSuccess: true,
  };
}

function VipGatewayBanner({ onClick }: { onClick: () => void }) {
  return (
    <div className="mt-0.5 flex items-center justify-between gap-3 rounded-lg border border-base-contrast-8 bg-primary/[0.06] px-3 py-2.5">
      <p className="min-w-0 text-3xs leading-relaxed text-base-contrast-50">
        VIP order gateway is available for faster order execution. Configure IP
        whitelist in Settings.
      </p>
      <button
        type="button"
        onClick={e => {
          e.preventDefault();
          e.stopPropagation();
          onClick();
        }}
        className="shrink-0 whitespace-nowrap rounded-full border border-primary bg-transparent px-3 text-3xs font-medium text-primary-light hover:opacity-90 focus:outline-none focus-visible:ring-2 focus-visible:ring-primary h-7"
      >
        View gateway
      </button>
    </div>
  );
}
