import { useCallback, useEffect, useMemo, useState } from "react";
import type { SymbolItem } from "../../../types";
import { ALL_STATUSES } from "../../../constants";
import {
  useBrokerListingOverview,
  DASHBOARD_OVERVIEW_SWR,
  whenDashboardPollingEnabled,
} from "../../../services";
import { useSelectListingStore } from "../../../store/useListingStore";
import { buildListingSymbolItem } from "../../../utils/buildListingSymbolItem";
import { PageView } from "../../../types";
import { useListingSymbolsData } from "../../../hooks/useListingSymbolsData";
import { useListingRiskSnapshotData } from "../../../hooks/useListingRiskSnapshotData";
import { useListingRefreshActions } from "../../../hooks/useListingRefreshActions";

export function useSymbolCardView() {
  const [page, setPage] = useState(1);
  const { pageSize, setDashboardSymbolsPageSize } = useSelectListingStore(
    state => ({
      pageSize: state.dashboardSymbolsPageSize,
      setDashboardSymbolsPageSize: state.setDashboardSymbolsPageSize,
    })
  );

  const isDashboardActive = useSelectListingStore(
    s => s.currentPage === PageView.Dashboard
  );
  const overview = useBrokerListingOverview(
    whenDashboardPollingEnabled(isDashboardActive, DASHBOARD_OVERVIEW_SWR)
  );
  const { statusFilter } = useSelectListingStore(state => ({
    statusFilter: state.statusFilter,
  }));
  const hasNoStatusFilter = statusFilter.length === 0;
  const statusQuery = useMemo(() => {
    if (statusFilter.length === 0) return undefined;
    if (statusFilter.length === ALL_STATUSES.length) return undefined;
    return statusFilter;
  }, [statusFilter]);
  const symbolsQuery = useListingSymbolsData(
    {
      page,
      size: pageSize,
      status: statusQuery,
    },
    { keepPreviousData: true }
  );
  const { listingSymbols, listingSymbolsTotal } = symbolsQuery;
  const total = hasNoStatusFilter ? 0 : listingSymbolsTotal;
  const riskSnapshotQuery = useListingRiskSnapshotData();
  const { riskSnapshot } = riskSnapshotQuery;
  const { refreshListingSymbols, refreshRiskSnapshot } =
    useListingRefreshActions();

  useEffect(() => {
    setPage(1);
  }, [statusFilter]);

  useEffect(() => {
    const pageTotal = Math.max(1, Math.ceil(total / pageSize));
    if (!symbolsQuery.isLoading && page > pageTotal) {
      setPage(pageTotal);
    }
  }, [total, page, pageSize, symbolsQuery.isLoading]);

  const symbolsAll = useMemo(() => {
    const rows = hasNoStatusFilter ? [] : (listingSymbols ?? []);
    const overviewBySymbol = new Map(
      (overview.data?.symbols ?? []).map(s => [s.symbol, s] as const)
    );
    const riskBySymbol = new Map(
      (riskSnapshot?.symbols ?? []).map(s => [s.symbol, s] as const)
    );

    return rows
      .map(row =>
        buildListingSymbolItem({ row, overviewBySymbol, riskBySymbol })
      )
      .filter((x): x is SymbolItem => x != null);
  }, [hasNoStatusFilter, listingSymbols, overview.data, riskSnapshot]);

  const isEmpty = total === 0 && statusFilter.length === ALL_STATUSES.length;

  const isLoading =
    symbolsQuery.isLoading ||
    symbolsQuery.isValidating ||
    overview.isLoading ||
    riskSnapshotQuery.isLoading;

  const onPageChange = useCallback((next: number) => setPage(next), []);

  const onPageSizeChange = useCallback(
    (size: number) => {
      setDashboardSymbolsPageSize(size);
      setPage(1);
    },
    [setDashboardSymbolsPageSize]
  );

  return {
    symbols: symbolsAll,
    page,
    pageSize,
    total,
    onPageChange,
    onPageSizeChange,
    overview,
    listingSymbols,
    mutateListingSymbols: refreshListingSymbols,
    riskSnapshot,
    mutateRiskSnapshot: refreshRiskSnapshot,
    isEmpty,
    isLoading,
  };
}
