export function SourceNameCell({
  item,
  isBuilderOracle,
  isBuilderLike,
  isOwnCustom,
  isThirdPartyCustom,
}: {
  item: SourceItem;
  isBuilderOracle: boolean;
  isBuilderLike: boolean;
  isOwnCustom: boolean;
  isThirdPartyCustom: boolean;
}) {
  const isPretgeOracle = isPretgeOracleSource(item);
  return (
    <td className="px-6 py-4 align-middle text-xs text-base-contrast-98 font-medium border-b border-base-contrast-6">
      <div className="inline-flex items-center gap-2">
        {isBuilderOracle ? <UptimeDot uptime7dPct={item.uptime7dPct} /> : null}
        <span>{item.name}</span>
        {isPretgeOracle ? (
          <span className="text-3xs font-medium text-base-contrast-36 whitespace-nowrap shrink-0">
            (Orderly-managed)
          </span>
        ) : isBuilderLike ? (
          <span className="inline-flex items-center gap-1.5 text-3xs font-medium text-base-contrast-36 whitespace-nowrap shrink-0">
            {isOwnCustom ? "(yours)" : "(other builder)"}
            {isThirdPartyCustom ? (
              <Tooltip
                content={item.riskNotice ?? THIRD_PARTY_SOURCE_TOOLTIP}
                side="top"
                sideOffset={6}
                className="max-w-[min(320px,90vw)] whitespace-normal text-left text-base-contrast-98"
              >
                <span className="inline-flex items-center text-warning">
                  <ExclamationFillIcon />
                </span>
              </Tooltip>
            ) : null}
          </span>
        ) : null}
      </div>
    </td>
  );
}

export function SourceTypeCell({ children }: { children: ReactNode }) {
  return (
    <td className="px-6 py-4 align-middle text-xs text-base-contrast-98 border-b border-base-contrast-6 whitespace-nowrap">
      {children}
    </td>
  );
}

export function SourceSymbolInputCell({
  value,
  hasError = false,
  readOnly = false,
  readOnlyTooltip,
  onChange,
  onBlur,
}: {
  value: string;
  hasError?: boolean;
  readOnly?: boolean;
  readOnlyTooltip?: string;
  onChange: (value: string) => void;
  onBlur?: () => void;
}) {
  const input = (
    <input
      value={value}
      onChange={e => {
        if (readOnly) return;
        onChange(e.target.value);
      }}
      onBlur={onBlur}
      readOnly={readOnly}
      className={cn(
        "w-full px-2 py-1 rounded text-3xs",
        "bg-base-300 text-base-contrast-98",
        "border outline-none",
        hasError
          ? "border-danger focus:border-danger"
          : "border-base-contrast-12 focus:border-primary/50",
        readOnly && "cursor-not-allowed opacity-50"
      )}
      placeholder={hasError ? "Enter symbol..." : undefined}
    />
  );

  return (
    <td className="px-6 py-4 align-middle border-b border-base-contrast-6">
      {readOnly && readOnlyTooltip ? (
        <Tooltip
          content={readOnlyTooltip}
          side="top"
          sideOffset={6}
          className="max-w-[min(260px,90vw)] whitespace-normal text-left"
        >
          <span className="block">{input}</span>
        </Tooltip>
      ) : (
        input
      )}
    </td>
  );
}

function EditableWeightCell({
  item,
  canEdit,
  onWeightChange,
}: {
  item: SourceItem;
  canEdit: boolean;
  onWeightChange: (id: string, weightPercent: number) => void;
}) {
  const displayWeight =
    typeof item.weight === "number" && Number.isFinite(item.weight)
      ? Math.round(item.weight)
      : 0;
  const [weightInput, setWeightInput] = useState(
    canEdit && displayWeight > 0 ? String(displayWeight) : ""
  );

  useEffect(() => {
    setWeightInput(canEdit && displayWeight > 0 ? String(displayWeight) : "");
  }, [canEdit, displayWeight]);

  return (
    <td
      className={cn(
        "px-4 py-4 align-middle text-xs tabular-nums border-b border-base-contrast-6 w-[92px] text-left",
        canEdit && item.weight > 0 ? "text-primary" : "text-base-contrast-98"
      )}
    >
      {canEdit ? (
        <input
          type="text"
          inputMode="numeric"
          value={weightInput}
          onChange={e => {
            const next = e.target.value.replace(/[^\d]/g, "");
            setWeightInput(next);
          }}
          onBlur={() => {
            const normalized = Math.max(
              1,
              Math.min(100, Math.round(Number(weightInput) || 1))
            );
            setWeightInput(String(normalized));
            onWeightChange(item.id, normalized);
          }}
          onKeyDown={e => {
            if (e.key === "Enter") {
              e.currentTarget.blur();
            }
          }}
          className={cn(
            "w-full h-8 px-2 rounded text-3xs text-left",
            "[appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none",
            "bg-base-300 text-base-contrast-98",
            "border border-base-contrast-12 outline-none",
            "focus:border-primary/50"
          )}
          aria-label={`Weight for ${item.name}`}
        />
      ) : (
        <div className="w-full h-8 px-2 flex items-center text-3xs text-base-contrast-36">
          -
        </div>
      )}
    </td>
  );
}

export function NotFoundSourceRow({
  item,
  canSelect,
  isBuilderOracle,
  isBuilderLike,
  isOwnCustom,
  isThirdPartyCustom,
  formattedItemType,
  onToggle,
  onSymbolChange,
  onSymbolBlur,
  onWeightChange,
}: {
  item: SourceItem;
  canSelect: boolean;
  isBuilderOracle: boolean;
  isBuilderLike: boolean;
  isOwnCustom: boolean;
  isThirdPartyCustom: boolean;
  formattedItemType: ReactNode;
  onToggle: (id: string) => void;
  onSymbolChange: (id: string, symbol: string) => void;
  onSymbolBlur: (id: string) => void;
  onWeightChange: (id: string, weightPercent: number) => void;
}) {
  const canEditWeight = canSelect && item.selected;

  return (
    <tr
      className={cn(
        "h-[52px] transition-colors",
        canSelect && item.selected
          ? "bg-primary/5 hover:bg-primary/[0.07]"
          : "hover:bg-base-contrast-4"
      )}
    >
      <td className="px-6 py-4 align-middle border-b border-base-contrast-6">
        <span className="inline-flex items-center h-[32px]">
          <input
            type="checkbox"
            checked={canSelect ? item.selected : false}
            disabled={!canSelect}
            onChange={canSelect ? () => onToggle(item.id) : undefined}
            className={cn(
              "w-4 h-4 accent-primary",
              canSelect
                ? "cursor-pointer"
                : "disabled:cursor-not-allowed disabled:opacity-50"
            )}
            aria-label={`Select ${item.name}`}
          />
        </span>
      </td>
      <SourceNameCell
        item={item}
        isBuilderOracle={isBuilderOracle}
        isBuilderLike={isBuilderLike}
        isOwnCustom={isOwnCustom}
        isThirdPartyCustom={isThirdPartyCustom}
      />
      <SourceTypeCell>{formattedItemType}</SourceTypeCell>
      <SourceSymbolInputCell
        value={item.sourceSymbol}
        hasError
        onChange={value => onSymbolChange(item.id, value)}
        onBlur={() => onSymbolBlur(item.id)}
      />
      <td className="px-6 py-4 align-middle text-3xs text-base-contrast-36 border-b border-base-contrast-6">
        -
      </td>
      <td className="px-6 py-4 align-middle text-xs text-danger border-b border-base-contrast-6">
        Not found on {item.name}
      </td>
      <td className="px-6 py-4 align-middle text-3xs text-base-contrast-36 border-b border-base-contrast-6">
        -
      </td>
      <EditableWeightCell
        item={item}
        canEdit={canEditWeight}
        onWeightChange={onWeightChange}
      />
    </tr>
  );
}
