import { Button } from "@/components/button";
import { Loader } from "@/components/loader";
import { useLocalizedPath } from "@/utils/localizedRoute";
import { SymbolCard } from "./SymbolCard";
import type { SymbolItem } from "../../../types";
import { useMarketInfoPriceChanges } from "../../../hooks/useMarketInfoPriceChanges";
import { formatListedAtLabel } from "../formatters";
import { useTranslation } from "@/i18n";
import { OdsSelect } from "@/components/orderly/OdsSelect";
import { SYMBOLS_PAGE_SIZE_OPTIONS } from "./constants";
import { usePermissionlessListingNavigation } from "../../../hooks/usePermissionlessListingNavigation";

interface SymbolCardViewUIProps {
  symbols: SymbolItem[];
  isEmpty: boolean;
  isLoading: boolean;
  page: number;
  pageSize: number;
  total: number;
  onCreateListing: () => void;
  onEdit?: (symbol: string) => void;
  onDelist?: (symbol: string) => void;
  onViewGateway?: () => void;
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;
}

export function SymbolCardViewUI({
  symbols,
  isEmpty,
  isLoading,
  page,
  pageSize,
  total,
  onCreateListing,
  onEdit,
  onDelist,
  onViewGateway,
  onPageChange,
  onPageSizeChange,
}: SymbolCardViewUIProps) {
  const { t } = useTranslation();
  const { getLastPrice } = useMarketInfoPriceChanges();
  const localizedPath = useLocalizedPath();
  const { handleSymbolLinkClick } = usePermissionlessListingNavigation();
  const pageTotal = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(page, pageTotal);
  const startIndex = total === 0 ? 0 : (safePage - 1) * pageSize + 1;
  const endIndex = Math.min(safePage * pageSize, total);

  if (isEmpty) {
    return <EmptyState onCreateListing={onCreateListing} />;
  }

  if (isLoading && symbols.length === 0) {
    return (
      <div className="flex items-center justify-center h-32 rounded-xl bg-base-200">
        <Loader />
      </div>
    );
  }

  if (symbols.length === 0) {
    return (
      <div className="flex items-center justify-center h-32 rounded-xl bg-base-200 text-sm text-base-contrast-36">
        {t("permissionlessListing.dashboard.noMatchingSymbols")}
      </div>
    );
  }

  return (
    <>
      <div className="relative">
        <div className="grid grid-cols-3 gap-4 items-stretch">
          {symbols.map(s => (
            <SymbolCard
              key={s.symbol}
              symbol={s}
              href={localizedPath(
                `/permissionless-listing/${encodeURIComponent(s.symbol)}`
              )}
              listedAtLabel={formatListedAtLabel(s.listedAt)}
              lastPrice={getLastPrice(s.symbol)}
              onView={event => handleSymbolLinkClick(event, s.symbol)}
              onEdit={onEdit ? () => onEdit(s.symbol) : undefined}
              onDelist={onDelist ? () => onDelist(s.symbol) : undefined}
              onViewGateway={onViewGateway}
            />
          ))}
        </div>
        {isLoading && (
          <div className="absolute inset-0 z-10 flex items-center justify-center rounded-xl bg-base-100/55 backdrop-blur-[1px]">
            <Loader />
          </div>
        )}
      </div>
      <SymbolsPaginationBar
        loading={isLoading}
        page={page}
        pageSize={pageSize}
        total={total}
        pageTotal={pageTotal}
        safePage={safePage}
        startIndex={startIndex}
        endIndex={endIndex}
        onPageChange={onPageChange}
        onPageSizeChange={onPageSizeChange}
      />
    </>
  );
}

function SymbolsPaginationBar(props: {
  loading: boolean;
  page: number;
  pageSize: number;
  total: number;
  pageTotal: number;
  safePage: number;
  startIndex: number;
  endIndex: number;
  onPageChange: (page: number) => void;
  onPageSizeChange: (size: number) => void;
}) {
  const { t } = useTranslation();
  const {
    loading,
    page,
    pageSize,
    total,
    pageTotal,
    safePage,
    startIndex,
    endIndex,
    onPageChange,
    onPageSizeChange,
  } = props;

  if (total === 0) return null;

  return (
    <div className="mt-4 px-4 py-3 flex items-center justify-between rounded-xl bg-base-200 border border-base-contrast-8">
      <div className="flex items-center gap-2 text-2xs text-base-contrast-54">
        <span>{t("permissionlessListing.dashboard.rowsPerPage")}</span>
        <OdsSelect
          value={String(pageSize)}
          disabled={loading}
          onChange={event => onPageSizeChange(Number(event.target.value))}
          containerClassName="w-[64px]"
          className="h-7 rounded-lg border-[rgba(255,255,255,0.06)] bg-base-300 focus-within:border-primary"
          selectClassName="px-3 pr-7 text-xs font-normal text-base-contrast-98"
        >
          {SYMBOLS_PAGE_SIZE_OPTIONS.map(size => (
            <option key={size} value={String(size)}>
              {size}
            </option>
          ))}
        </OdsSelect>
      </div>

      <div className="flex items-center gap-3 text-2xs text-base-contrast-54">
        <span>
          {loading
            ? t("permissionlessListing.dashboard.loading")
            : t("permissionlessListing.dashboard.showingRows", {
                start: startIndex,
                end: endIndex,
                total,
              })}
        </span>
        <button
          type="button"
          className="h-7 min-w-7 px-2 rounded-md bg-base-300 border border-base-contrast-12 text-base-contrast-98 disabled:opacity-40"
          disabled={loading || safePage <= 1}
          onClick={() => onPageChange(Math.max(1, safePage - 1))}
        >
          {t("permissionlessListing.dashboard.prev")}
        </button>
        <span className="text-base-contrast-80">
          {loading ? `${page}/...` : `${safePage}/${pageTotal}`}
        </span>
        <button
          type="button"
          className="h-7 min-w-7 px-2 rounded-md bg-base-300 border border-base-contrast-12 text-base-contrast-98 disabled:opacity-40"
          disabled={loading || safePage >= pageTotal}
          onClick={() => onPageChange(Math.min(pageTotal, safePage + 1))}
        >
          {t("permissionlessListing.dashboard.next")}
        </button>
      </div>
    </div>
  );
}

function EmptyState({ onCreateListing }: { onCreateListing: () => void }) {
  const { t } = useTranslation();

  return (
    <div className="flex flex-col items-center justify-center gap-4 py-16 px-4 rounded-xl bg-base-200 text-center">
      <p className="text-sm font-medium leading-tight text-base-contrast-98">
        {t("permissionlessListing.dashboard.emptyTitle")}
      </p>
      <p className="text-sm font-medium leading-snug text-base-contrast-50 max-w-[400px]">
        {t("permissionlessListing.dashboard.emptyDescription")}
      </p>
      <Button
        onClick={onCreateListing}
        size="md"
        rounded="full"
        className="flex items-center gap-1.5 px-5 h-8 text-sm font-medium"
      >
        <span className="text-base leading-none">+</span>
        {t("permissionlessListing.dashboard.createListing")}
      </Button>
    </div>
  );
}
