import { cn } from "@/utils/css";
import type { SymbolStatus } from "../types";
import { STATUS_CONFIG } from "../constants";
import { useTranslation } from "@/i18n";

interface StatusBadgeProps {
  status: SymbolStatus;
  className?: string;
  depthPct?: number;
}

export function StatusBadge({
  status,
  className,
  depthPct: _depthPct,
}: StatusBadgeProps) {
  const { t } = useTranslation();
  const config = STATUS_CONFIG[status];

  return (
    <span
      className={cn(
        "inline-flex items-center text-3xs font-medium px-2.5 py-0.5 rounded-full",
        config.color,
        config.bgColor,
        className
      )}
    >
      {getStatusLabel(t, status)}
    </span>
  );
}

export function getStatusLabel(
  t: ReturnType<typeof useTranslation>["t"],
  status: SymbolStatus
) {
  switch (status) {
    case "NEW":
      return t("permissionlessListing.status.new");
    case "PENDING":
      return t("permissionlessListing.status.pending");
    case "POST_ONLY":
      return t("permissionlessListing.status.postOnly");
    case "ACTIVE":
      return t("permissionlessListing.status.active");
    case "REDUCE_ONLY":
      return t("permissionlessListing.status.reduceOnly");
    case "DELISTING":
      return t("permissionlessListing.status.delisting");
    case "DELISTED":
      return t("permissionlessListing.status.delisted");
  }
}
