import type { IndexSourceMeta, SourceItem, SymbolDetail } from "../types";
import { IndexSourceType, ListingAssetType } from "../types";
import {
  fxSourceKeyToItemId,
  getSourceDisplayMeta,
  matchIndexSourceCatalog,
  normalizeMappingType,
  normalizeSourceKey,
  resolveApiSource,
  shouldUseFxSourceRowId,
  sourceKeyToItemId,
} from "../services";
import { isPretgeOracleSource, normalizePretgeSourceType } from "./pretge";
import { normalizeStoredWeightPercentInt } from "../sections/listing/price-sources/hooks/shared";

export function getListingAssetTypeFromDetail(detail: SymbolDetail) {
  return detail.isRwa ? ListingAssetType.Rwa : ListingAssetType.Crypto;
}

export function buildSourceItemsFromDetailForEdit(
  detail: SymbolDetail,
  catalog: IndexSourceMeta[]
): SourceItem[] {
  const rows = detail.indexSources;
  if (!rows.length) return [];

  const equalWeight = Math.round(100 / rows.length);

  return rows.map(rawSource => {
    const source = normalizePretgeSourceType(rawSource);
    const isPretgeOracle = isPretgeOracleSource(source);
    const catRow = matchIndexSourceCatalog(catalog, source.source);
    const def = getSourceDisplayMeta(catRow?.source ?? source.source);
    const apiKey = isPretgeOracle
      ? source.source
      : (def?.source ??
        catRow?.source ??
        resolveApiSource(source.source) ??
        normalizeSourceKey(source.source));
    const mappingType = normalizeMappingType(source.mappingType);
    const normalizedWeight = normalizeStoredWeightPercentInt(
      source.weight ?? 0
    );

    return {
      id:
        mappingType && shouldUseFxSourceRowId({ source: apiKey, mappingType })
          ? fxSourceKeyToItemId(apiKey, source.sourceSymbol, mappingType)
          : sourceKeyToItemId(apiKey),
      source: apiKey,
      sourceId: source.sourceId,
      name: catRow?.name ?? def?.name ?? source.source,
      type: isPretgeOracle
        ? IndexSourceType.PretgeOracle
        : ((source.type as SourceItem["type"]) ??
          catRow?.type ??
          IndexSourceType.Cex),
      found: true,
      sourceSymbol: source.sourceSymbol,
      multiplier: source.priceMultiplier,
      mappingType,
      price: source.latestPrice,
      volume24h: 0,
      weight: normalizedWeight || equalWeight,
      selected: true,
      loading: false,
    };
  });
}
