import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from "react";
import { cn } from "@/utils/css";
import { Button } from "@/components/button";
import { PLInput } from "./Input";
import { useUpdateBrokerListingConfig } from "../services/brokerListing";
import { toast } from "@/components/toast";
import { useListingServerData } from "../hooks/useListingServerData";
import { useListingRefreshActions } from "../hooks/useListingRefreshActions";

export type TelegramChatIdFieldHandle = {
  saveIfDirty: () => Promise<void>;
};

export type TelegramChatIdFieldProps = {
  labelText?: string;
  placeholder?: string;
  labelClassName?: string;
  inputClassName?: string;
  containerClassName?: string;
  /**
   * Called whenever the underlying request is in-flight.
   * Useful for parent buttons to reflect a "Saving..." state.
   */
  onSavingChange?: (isSaving: boolean) => void;
};

export const TelegramChatIdField = forwardRef<
  TelegramChatIdFieldHandle,
  TelegramChatIdFieldProps
>(
  (
    {
      labelText = "Telegram Chat ID",
      placeholder = "e.g. -1001234567890",
      labelClassName,
      inputClassName,
      containerClassName,
      onSavingChange,
    },
    ref
  ) => {
    const { listingConfig, listingConfigQuery } = useListingServerData();
    const { refreshConfig } = useListingRefreshActions();
    const [updateConfig] = useUpdateBrokerListingConfig();

    const [value, setValue] = useState<string>(
      () => listingConfig.tg_chat_id ?? ""
    );
    const [saveError, setSaveError] = useState(false);
    const [isSaving, setIsSaving] = useState(false);
    const [optimisticSavedValue, setOptimisticSavedValue] = useState<
      string | null
    >(null);
    const nextValue = value.trim();
    const savedValue = (listingConfig.tg_chat_id ?? "").trim();
    const effectiveSavedValue = optimisticSavedValue ?? savedValue;
    const isDirty = nextValue !== effectiveSavedValue;
    const canSave = isDirty && nextValue !== "" && !isSaving;

    const inFlightRef = useRef<Promise<void> | null>(null);

    useEffect(() => {
      if (isSaving) return;
      if (listingConfigQuery.data === undefined) return;
      if (
        optimisticSavedValue !== null &&
        savedValue !== optimisticSavedValue
      ) {
        return;
      }
      setOptimisticSavedValue(null);
      setValue(listingConfig.tg_chat_id ?? "");
    }, [
      isSaving,
      listingConfig.tg_chat_id,
      listingConfigQuery.data,
      optimisticSavedValue,
      savedValue,
    ]);

    useEffect(() => {
      onSavingChange?.(isSaving);
    }, [onSavingChange, isSaving]);

    const saveIfDirty = useCallback(async () => {
      // No change -> no request.
      if (!isDirty) {
        setSaveError(false);
        return;
      }
      // Empty chat id -> keep the request explicit and local to the Save button.
      if (nextValue === "") {
        setSaveError(true);
        toast.error("Telegram chat ID is required");
        return;
      }

      if (inFlightRef.current) return inFlightRef.current;

      setIsSaving(true);
      const p = (async () => {
        try {
          const res = await updateConfig({ tg_chat_id: nextValue });
          if (!res?.success) {
            throw res;
          }
          await refreshConfig();
          setOptimisticSavedValue(nextValue);
          setValue(nextValue);
          setSaveError(false);
          toast.success("Telegram chat ID saved");
        } catch (e: unknown) {
          setOptimisticSavedValue(null);
          toast.error(
            (e as { message?: string })?.message ||
              "Failed to update Telegram chat id"
          );
          setSaveError(true);
        }
      })();

      inFlightRef.current = p;
      try {
        await p;
      } finally {
        inFlightRef.current = null;
        setIsSaving(false);
      }
    }, [isDirty, nextValue, refreshConfig, updateConfig]);

    useImperativeHandle(ref, () => ({ saveIfDirty }), [saveIfDirty]);

    const handleChange = useCallback(
      (e: React.ChangeEvent<HTMLInputElement>) => {
        setSaveError(false);
        setValue(e.target.value.replace(/[^\d-]/g, ""));
      },
      []
    );

    return (
      <div className={cn("flex flex-col gap-2", containerClassName)}>
        <label
          className={cn("font-medium text-base-contrast-50", labelClassName)}
        >
          {labelText}
        </label>
        <div className="flex gap-2">
          <PLInput
            type="text"
            value={value}
            onChange={handleChange}
            placeholder={placeholder}
            error={saveError}
            className={inputClassName}
          />
          <Button
            type="button"
            size="sm"
            rounded="lg"
            onClick={saveIfDirty}
            loading={isSaving}
            disabled={!canSave}
            className="h-auto min-h-[40px] shrink-0 px-4 w-[65px]"
          >
            Save
          </Button>
        </div>
      </div>
    );
  }
);

TelegramChatIdField.displayName = "TelegramChatIdField";
