import { walletGetItem } from "@/utils/storage";

export function getDexCreatorAuthHeaders(): HeadersInit | null {
  if (typeof window === "undefined") return null;

  const token = walletGetItem("auth_token");
  if (!token) return null;

  return {
    Authorization: `Bearer ${token}`,
  };
}

export function notifyDexCreatorAuthExpired() {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent("authTokenExpired"));
}
