import { useCallback, useEffect } from "react";
import type { MouseEvent as ReactMouseEvent } from "react";
import { useLocalizedPath } from "@/utils/localizedRoute";
import { useSelectListingStore } from "../store/useListingStore";
import { PageView } from "../types";

const DASHBOARD_PATH = "/permissionless-listing";

function getSymbolDetailPath(symbol: string): string {
  return `${DASHBOARD_PATH}/${encodeURIComponent(symbol)}`;
}

function parsePermissionlessListingPath(
  pathname: string
):
  | { page: PageView.Dashboard }
  | { page: PageView.SymbolDetail; symbol: string }
  | null {
  const normalized = pathname.replace(/\/+$/, "") || "/";
  const match = normalized.match(
    /^\/(?:[^/]+\/)?permissionless-listing(?:\/([^/]+))?$/
  );
  if (!match) return null;

  const encodedSymbol = match[1];
  if (!encodedSymbol) return { page: PageView.Dashboard };
  if (encodedSymbol.includes("/")) return null;

  try {
    return {
      page: PageView.SymbolDetail,
      symbol: decodeURIComponent(encodedSymbol),
    };
  } catch {
    return null;
  }
}

function shouldHandleLinkClick(event: ReactMouseEvent<HTMLElement>): boolean {
  if (event.defaultPrevented) return false;
  if (event.button !== 0) return false;
  if (event.metaKey || event.altKey || event.ctrlKey || event.shiftKey) {
    return false;
  }

  const target = event.currentTarget.getAttribute("target");
  return !target || target === "_self";
}

export function usePermissionlessListingNavigation() {
  const localizedPath = useLocalizedPath();
  const { setPage } = useSelectListingStore(s => ({
    setPage: s.setPage,
  }));

  const navigateToDashboard = useCallback(() => {
    const nextPath = localizedPath(DASHBOARD_PATH);
    window.history.replaceState(null, "", nextPath);
    setPage(PageView.Dashboard);
  }, [localizedPath, setPage]);

  const navigateToSymbolDetail = useCallback(
    (symbol: string) => {
      const nextPath = localizedPath(getSymbolDetailPath(symbol));
      if (window.location.pathname === nextPath) {
        window.history.replaceState(null, "", nextPath);
      } else {
        window.history.pushState(null, "", nextPath);
      }
      setPage(PageView.SymbolDetail, { symbol });
    },
    [localizedPath, setPage]
  );

  const handleSymbolLinkClick = useCallback(
    (event: ReactMouseEvent<HTMLElement>, symbol: string) => {
      if (!shouldHandleLinkClick(event)) return;

      event.preventDefault();
      navigateToSymbolDetail(symbol);
    },
    [navigateToSymbolDetail]
  );

  return {
    navigateToDashboard,
    navigateToSymbolDetail,
    handleSymbolLinkClick,
  };
}

export function usePermissionlessListingHistorySync() {
  const { setPage } = useSelectListingStore(s => ({
    setPage: s.setPage,
  }));

  useEffect(() => {
    const syncFromBrowserHistory = () => {
      const routeState = parsePermissionlessListingPath(
        window.location.pathname
      );
      if (!routeState) return;

      if (routeState.page === PageView.SymbolDetail) {
        setPage(PageView.SymbolDetail, { symbol: routeState.symbol });
        return;
      }

      setPage(PageView.Dashboard);
    };

    window.addEventListener("popstate", syncFromBrowserHistory);
    return () => {
      window.removeEventListener("popstate", syncFromBrowserHistory);
    };
  }, [setPage]);
}
