"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type SetStateAction,
} from "react";
import { ListingAssetType } from "../../../../types";
import type {
  IndexSourceMeta,
  SourceItem,
  SymbolDetail,
} from "../../../../types";
import { useSelectListingStore } from "../../../../store/useListingStore";
import {
  isBrokerListingFxSourceItem,
  isBrokerListingFxSourceKey,
  sourceKeyToItemId,
  useGetBrokerListingIndexSources,
  useGetBuilderSources,
  useGetBrokerListingFxSources,
  useGetBrokerListingPretgeSources,
  useCheckBrokerListingSymbolContext,
} from "../../../../services";
import type {
  BrokerListingBuilderSourceRow,
  BrokerListingFxSourceRow,
  BrokerListingIndexSourceRow,
  BrokerListingPretgeSourceRow,
} from "../../../../services";
import { enrichIndexSources } from "../../../../services/priceSources";
import { mergeBuilderSourceRows } from "../../../../services";
import {
  PriceSourceWeightMode,
  SEARCH_DEBOUNCE_MS,
  buildSavedMergeMapByRowId,
  getListingBaseFromSymbol,
  preserveOrRecalcWeights,
  type SavedRowMerge,
} from "./shared";
import {
  isBuilderLikeSourceType,
  sortSourcesForDisplay,
} from "./rules.helpers";
import { useSearchRequestLifecycle } from "./useSearchRequestLifecycle";
import {
  applySourcePatch,
  buildFxInitialSourceRows,
  buildInitialSourceRows,
  buildOptimisticEditSourceRows,
  buildPretgeFallbackRowsFromDetail,
  buildPretgeInitialSourceRows,
  fetchQuotePatchForSource,
  getSearchEditContext,
  getSearchWeightMode,
  mergeSourceRowsById,
  normalizeIndexSourceApiRows,
} from "./search.helpers";
import { toast } from "@/components/toast";
import { isCompactFxPair } from "@/shared/fx";
import { isPretgeOracleSource } from "../../../../utils/pretge";

export type GetBrokerListingSymbolContextFn = (input: {
  symbol: string;
  is_pretge?: boolean;
}) => Promise<
  { success: boolean; data?: { is_rwa?: boolean } } & Record<string, unknown>
>;

type SymbolContextEnvelope = {
  success?: boolean;
  data?: { is_rwa?: boolean };
};

export type UsePriceSourcesSearchParams = {
  priceSources: SourceItem[];
  setPriceSources: (sources: SourceItem[]) => void;
  editMode: boolean;
  editSymbol: string | null;
  symbolDetails: Record<string, SymbolDetail>;
  indexSources: IndexSourceMeta[];
};

type RowsEnvelope<T> = {
  data?: T[] | { rows?: T[] };
  rows?: T[];
};

function extractRows<T>(response: unknown): T[] {
  if (Array.isArray(response)) return response as T[];
  if (typeof response !== "object" || response === null) return [];

  const envelope = response as RowsEnvelope<T>;
  if (Array.isArray(envelope.rows)) return envelope.rows;
  if (Array.isArray(envelope.data)) return envelope.data;
  if (
    typeof envelope.data === "object" &&
    envelope.data !== null &&
    Array.isArray(envelope.data.rows)
  ) {
    return envelope.data.rows;
  }
  return [];
}

function getApiErrorMessage(error: unknown): string | undefined {
  if (error instanceof Error) return error.message;
  if (typeof error !== "object" || error === null) return undefined;
  const message = (error as { message?: unknown }).message;
  return typeof message === "string" ? message : undefined;
}

/** Symbol search input: ASCII letters and digits only. */
function sanitizePriceSourcesSearchInput(value: string): string {
  return value.replace(/[^A-Za-z0-9]/g, "");
}

export function usePriceSourcesSearch({
  priceSources,
  setPriceSources,
  editMode,
  editSymbol,
  symbolDetails,
  indexSources,
}: UsePriceSourcesSearchParams) {
  const {
    currentListingBase,
    listingAssetType,
    isPretge,
    resumePriceSourcesFromCustomOracle,
    setCurrentListingBase,
    setIndexSources,
    setResumePriceSourcesFromCustomOracle,
  } = useSelectListingStore(s => ({
    currentListingBase: s.currentListingBase,
    listingAssetType: s.listingAssetType,
    isPretge: s.isPretge,
    resumePriceSourcesFromCustomOracle: s.resumePriceSourcesFromCustomOracle,
    setCurrentListingBase: s.setCurrentListingBase,
    setIndexSources: s.setIndexSources,
    setResumePriceSourcesFromCustomOracle:
      s.setResumePriceSourcesFromCustomOracle,
  }));

  const [searchTerm, setSearchTermState] = useState(() =>
    sanitizePriceSourcesSearchInput(
      resumePriceSourcesFromCustomOracle && editMode && editSymbol
        ? getListingBaseFromSymbol(editSymbol)
        : currentListingBase
    )
  );
  const skipInitialSearchFromCustomOracleRef = useRef(
    resumePriceSourcesFromCustomOracle && priceSources.length > 0
  );

  const setSearchTerm = useCallback((update: SetStateAction<string>) => {
    setSearchTermState(prev => {
      const next = typeof update === "function" ? update(prev) : update;
      return sanitizePriceSourcesSearchInput(next);
    });
  }, []);
  const [fetchIndexSourcesByBase] = useGetBrokerListingIndexSources();
  const [fetchBuilderSourcesByBase] = useGetBuilderSources();
  const [fetchFxSourcesByBase] = useGetBrokerListingFxSources();
  const [fetchPretgeSourcesByBase] = useGetBrokerListingPretgeSources();

  const {
    searching,
    setSearching,
    lastTriggeredSearchRef,
    searchReqIdRef,
    searchTimerRef,
    sourcesRef,
    editSearchHydratedForSymbolRef,
    initialOrderByIdRef,
    publishSources,
    beginSearchRequest,
    cancelCurrentSearch,
    isCurrentRequest,
  } = useSearchRequestLifecycle({ priceSources, setPriceSources });

  const [checkSymbolContext] = useCheckBrokerListingSymbolContext();

  const sortDisplaySources = useCallback(
    (items: SourceItem[]) =>
      sortSourcesForDisplay(items, initialOrderByIdRef.current),
    [initialOrderByIdRef]
  );

  const publishNormalizedSources = useCallback(
    (items: SourceItem[], weightMode: PriceSourceWeightMode) => {
      publishSources(
        sortDisplaySources(preserveOrRecalcWeights(items, weightMode))
      );
    },
    [publishSources, sortDisplaySources]
  );

  const fetchAndMergeBuilderSources = useCallback(
    async (input: {
      baseSymbol: string;
      reqId: number;
      toastOnError: boolean;
    }) => {
      const normalizedBase = input.baseSymbol.trim().toUpperCase();
      if (!normalizedBase) return;

      try {
        const res = await fetchBuilderSourcesByBase({
          base_ccy: normalizedBase,
        });
        const safeRows = extractRows<BrokerListingBuilderSourceRow>(res);
        if (!isCurrentRequest(input.reqId)) return [];

        const merged = mergeBuilderSourceRows(sourcesRef.current, safeRows);
        publishSources(sortDisplaySources(merged));
      } catch {
        if (!isCurrentRequest(input.reqId)) return [];
        if (input.toastOnError) {
          toast.error("Failed to fetch builder sources. Please try again.");
        }
        const merged = mergeBuilderSourceRows(sourcesRef.current, []);
        publishSources(sortDisplaySources(merged));
      }
    },
    [
      fetchBuilderSourcesByBase,
      isCurrentRequest,
      publishSources,
      sortDisplaySources,
      sourcesRef,
    ]
  );

  const refetchBuilderSources = useCallback(
    async (baseSymbol?: string) => {
      const normalizedBase = (baseSymbol ?? searchTerm).trim().toUpperCase();
      if (!normalizedBase) return;
      await fetchAndMergeBuilderSources({
        baseSymbol: normalizedBase,
        reqId: searchReqIdRef.current,
        toastOnError: false,
      });
    },
    [fetchAndMergeBuilderSources, searchReqIdRef, searchTerm]
  );

  const fetchAndMergeFxSources = useCallback(
    async (input: {
      baseSymbol: string;
      reqId: number;
      savedMap: Map<string, SavedRowMerge> | null;
      weightMode: PriceSourceWeightMode;
    }): Promise<BrokerListingFxSourceRow[]> => {
      const normalizedBase = input.baseSymbol.trim().toUpperCase();
      if (
        listingAssetType !== ListingAssetType.Rwa ||
        !isCompactFxPair(normalizedBase)
      ) {
        return [];
      }

      try {
        const res = await fetchFxSourcesByBase({
          base_ccy: normalizedBase,
          active_only: true,
        });
        if (!isCurrentRequest(input.reqId)) return [];

        const fxRows = extractRows<BrokerListingFxSourceRow>(res);
        const fxItems = buildFxInitialSourceRows({
          rows: fxRows,
          savedMap: input.savedMap,
        });
        const merged = mergeSourceRowsById({
          base: sourcesRef.current,
          next: fxItems,
        });
        publishNormalizedSources(merged, input.weightMode);
        return fxRows;
      } catch {
        if (!isCurrentRequest(input.reqId)) return [];
        toast.error("Failed to fetch FX sources. Please try again.");
        return [];
      }
    },
    [
      fetchFxSourcesByBase,
      isCurrentRequest,
      listingAssetType,
      publishNormalizedSources,
      sourcesRef,
    ]
  );

  const fetchAndMergePretgeSources = useCallback(
    async (input: {
      baseSymbol: string;
      reqId: number;
      savedMap: Map<string, SavedRowMerge> | null;
      weightMode: PriceSourceWeightMode;
      enabled: boolean;
    }): Promise<BrokerListingPretgeSourceRow[]> => {
      const normalizedBase = input.baseSymbol.trim().toUpperCase();
      if (!normalizedBase || !input.enabled) {
        return [];
      }

      try {
        const res = await fetchPretgeSourcesByBase({
          base_ccy: normalizedBase,
        });
        if (!isCurrentRequest(input.reqId)) return [];

        const pretgeRows = extractRows<BrokerListingPretgeSourceRow>(res);
        const pretgeItems = buildPretgeInitialSourceRows({
          rows: pretgeRows,
          savedMap: input.savedMap,
        });
        const merged = mergeSourceRowsById({
          base: sourcesRef.current,
          next: pretgeItems,
        });
        publishNormalizedSources(merged, input.weightMode);
        return pretgeRows;
      } catch {
        if (!isCurrentRequest(input.reqId)) return [];
        toast.error("Failed to fetch Pre-TGE sources. Please try again.");
        return [];
      }
    },
    [
      fetchPretgeSourcesByBase,
      isCurrentRequest,
      publishNormalizedSources,
      sourcesRef,
    ]
  );

  useEffect(() => {
    if (editMode) return;
    setCurrentListingBase(searchTerm.trim().toUpperCase());
  }, [editMode, searchTerm, setCurrentListingBase]);

  const onError = useCallback(
    (e: unknown) => {
      setSearching(false);
      publishSources([]);
      toast.error(
        getApiErrorMessage(e) || "Failed to validate symbol. Please try again."
      );
    },
    [publishSources, setSearching]
  );

  const searchSources = useCallback(
    async (
      baseSymbol: string,
      options?: { preserveExistingWeights?: boolean }
    ) => {
      const normalizedBase = baseSymbol.trim().toUpperCase();
      if (!normalizedBase) return;
      const preserveExistingWeights = options?.preserveExistingWeights ?? false;
      const shouldFetchFxSources =
        listingAssetType === ListingAssetType.Rwa &&
        isCompactFxPair(normalizedBase);
      const reqId = beginSearchRequest();
      const abortSearchWithAssetTypeMismatchToast = () => {
        if (!isCurrentRequest(reqId)) return;
        setSearching(false);
        publishSources([]);
        toast.error(
          "No matching symbol found under the selected asset type. Try another asset type if needed."
        );
      };
      const { detail, mergeDetail } = getSearchEditContext({
        editMode,
        editSymbol,
        symbolDetails,
        normalizedBase,
      });
      const effectiveAssetType = listingAssetType ?? ListingAssetType.Crypto;
      const shouldFetchPretgeSources =
        effectiveAssetType === ListingAssetType.Crypto;
      const shouldValidateAsPretge =
        effectiveAssetType === ListingAssetType.Crypto && isPretge;
      const savedMap =
        mergeDetail && detail
          ? buildSavedMergeMapByRowId(detail, indexSources)
          : null;
      const pretgeFallbackRows = mergeDetail
        ? buildPretgeFallbackRowsFromDetail({ detail, savedMap })
        : [];
      const weightMode = getSearchWeightMode({
        mergeDetail,
        preserveExistingWeights,
      });
      const optimisticEditRows =
        editMode && savedMap
          ? mergeSourceRowsById({
              base: buildOptimisticEditSourceRows({
                catalog: indexSources,
                normalizedBase,
                savedMap,
              }).filter(row => !isBrokerListingFxSourceKey(row.source)),
              next: pretgeFallbackRows,
            })
          : [];

      if (optimisticEditRows.length > 0) {
        initialOrderByIdRef.current = new Map(
          optimisticEditRows.map((s, idx) => [s.id, idx])
        );
        publishNormalizedSources(optimisticEditRows, weightMode);
      } else if (editMode && sourcesRef.current.length > 0) {
        publishSources(
          sourcesRef.current.map(source => ({
            ...source,
            priceLoading: true,
            volumeLoading: true,
            notFound: false,
          }))
        );
      }

      // Keep the base-filtered index source catalog fresh on re-search.
      // This is intentionally tied to the current `searchTerm` query key.
      let refreshedIndexSourcesByBase: unknown = undefined;
      try {
        refreshedIndexSourcesByBase = await fetchIndexSourcesByBase({
          base_ccy: normalizedBase,
        });
      } catch {
        if (!isCurrentRequest(reqId)) return;
        setSearching(false);
        publishSources([]);
        toast.error("Failed to fetch index sources. Please try again.");
        return;
      }

      // In edit mode we already have the symbol details from store, so we
      // don't need to fetch broker listing symbol context again.
      if (!editMode) {
        try {
          const res = (await checkSymbolContext({
            symbol: normalizedBase,
            is_pretge: shouldValidateAsPretge,
          })) as unknown as SymbolContextEnvelope;
          if (!res.success) {
            throw res;
          }
          const isRwaSymbol = res?.data?.is_rwa === true;
          const assetTypeMismatch =
            (effectiveAssetType === ListingAssetType.Crypto && isRwaSymbol) ||
            (effectiveAssetType === ListingAssetType.Rwa && !isRwaSymbol);
          if (assetTypeMismatch) {
            abortSearchWithAssetTypeMismatchToast();
            return;
          }
        } catch (e: unknown) {
          if (!isCurrentRequest(reqId)) return;
          onError(e);
          return;
        }
      }

      // Must rely on base-filtered API rows (contains source_symbol/source_id).
      // If missing, stop search and surface an actionable error.
      const baseRowsRaw = extractRows<BrokerListingIndexSourceRow>(
        refreshedIndexSourcesByBase
      );

      const apiRows = normalizeIndexSourceApiRows(baseRowsRaw);
      const candidateApiRows = apiRows.filter(
        row =>
          !isBrokerListingFxSourceKey(row.source) && !isPretgeOracleSource(row)
      );
      if (
        candidateApiRows.length === 0 &&
        !shouldFetchFxSources &&
        !shouldFetchPretgeSources
      ) {
        if (isCurrentRequest(reqId)) {
          setSearching(false);
          publishSources([]);
          toast.error("Failed to fetch index sources. Please try again.");
        }
        return;
      }

      // Keep the global catalog in sync with base-filtered results for
      // downstream pages within the listing flow.
      const newIndexSources = enrichIndexSources(candidateApiRows);
      setIndexSources(newIndexSources);

      const items = mergeSourceRowsById({
        base: buildInitialSourceRows({
          apiRows: candidateApiRows,
          normalizedBase,
          savedMap,
        }),
        next: pretgeFallbackRows,
      });

      initialOrderByIdRef.current = new Map(items.map((s, idx) => [s.id, idx]));

      publishNormalizedSources(items, weightMode);

      const fxRowsPromise = fetchAndMergeFxSources({
        baseSymbol: normalizedBase,
        reqId,
        savedMap,
        weightMode,
      });
      const pretgeRowsPromise = fetchAndMergePretgeSources({
        baseSymbol: normalizedBase,
        reqId,
        savedMap,
        weightMode,
        enabled: shouldFetchPretgeSources,
      });

      // Builder Oracle / BYOK rows are resolved by merging builder_sources rows.
      // Trigger it after candidates are set so loading placeholders can be replaced.
      await Promise.allSettled([
        ...(newIndexSources.some(row => isBuilderLikeSourceType(row.type))
          ? [
              fetchAndMergeBuilderSources({
                baseSymbol: normalizedBase,
                reqId,
                toastOnError: true,
              }),
            ]
          : []),
        fxRowsPromise,
        pretgeRowsPromise,
        ...newIndexSources
          .filter(
            row =>
              !isBuilderLikeSourceType(row.type) &&
              !isBrokerListingFxSourceItem(row) &&
              !isPretgeOracleSource(row)
          )
          .map(async row => {
            const rowId = sourceKeyToItemId(row.source);
            const saved = savedMap?.get(rowId);
            const fxRows =
              shouldFetchFxSources && row.source === "PYTH"
                ? await fxRowsPromise
                : [];
            const result = await fetchQuotePatchForSource({
              row,
              normalizedBase,
              saved,
              mergeDetail,
              listingAssetType: listingAssetType ?? undefined,
              fxRows,
            });
            if (!isCurrentRequest(reqId)) return;
            const updated = applySourcePatch({
              sources: sourcesRef.current,
              rowId: result.rowId,
              patch: result.patch,
            });
            publishNormalizedSources(updated, weightMode);
          }),
      ]);

      if (isCurrentRequest(reqId)) {
        const pretgeRows = await pretgeRowsPromise;
        if (
          candidateApiRows.length === 0 &&
          !shouldFetchFxSources &&
          shouldFetchPretgeSources &&
          pretgeFallbackRows.length === 0 &&
          pretgeRows.length === 0
        ) {
          publishSources([]);
          toast.error("Failed to fetch index sources. Please try again.");
        }
        setSearching(false);
      }
    },
    [
      editMode,
      editSymbol,
      checkSymbolContext,
      beginSearchRequest,
      initialOrderByIdRef,
      indexSources,
      isCurrentRequest,
      listingAssetType,
      isPretge,
      onError,
      publishSources,
      publishNormalizedSources,
      symbolDetails,
      sourcesRef,
      fetchIndexSourcesByBase,
      fetchAndMergeBuilderSources,
      fetchAndMergeFxSources,
      fetchAndMergePretgeSources,
      setIndexSources,
      setSearching,
    ]
  );

  useEffect(() => {
    if (!editMode) {
      editSearchHydratedForSymbolRef.current = null;
    }
  }, [editMode, editSearchHydratedForSymbolRef]);

  useEffect(() => {
    if (!resumePriceSourcesFromCustomOracle) return;

    const base =
      editMode && editSymbol
        ? getListingBaseFromSymbol(editSymbol)
        : currentListingBase;
    const normalizedBase = base.trim().toUpperCase();

    if (normalizedBase && sourcesRef.current.length > 0) {
      lastTriggeredSearchRef.current = normalizedBase;
      if (editMode && editSymbol) {
        editSearchHydratedForSymbolRef.current = editSymbol;
      }
      setSearchTerm(normalizedBase);
      cancelCurrentSearch();
    }

    setResumePriceSourcesFromCustomOracle(false);
  }, [
    cancelCurrentSearch,
    currentListingBase,
    editMode,
    editSearchHydratedForSymbolRef,
    editSymbol,
    lastTriggeredSearchRef,
    resumePriceSourcesFromCustomOracle,
    setResumePriceSourcesFromCustomOracle,
    setSearchTerm,
    sourcesRef,
  ]);

  useEffect(() => {
    if (!editMode || !editSymbol) return;
    const detail = symbolDetails[editSymbol];
    if (!detail) return;
    if (editSearchHydratedForSymbolRef.current === editSymbol) return;
    const base = getListingBaseFromSymbol(editSymbol);
    if (!base) return;
    if (
      skipInitialSearchFromCustomOracleRef.current &&
      sourcesRef.current.length > 0
    ) {
      editSearchHydratedForSymbolRef.current = editSymbol;
      lastTriggeredSearchRef.current = base.trim().toUpperCase();
      setSearchTerm(base);
      skipInitialSearchFromCustomOracleRef.current = false;
      return;
    }
    editSearchHydratedForSymbolRef.current = editSymbol;
    lastTriggeredSearchRef.current = base.trim().toUpperCase();
    setSearchTerm(base);
    void searchSources(base, { preserveExistingWeights: true });
  }, [
    editMode,
    editSymbol,
    editSearchHydratedForSymbolRef,
    lastTriggeredSearchRef,
    setSearchTerm,
    skipInitialSearchFromCustomOracleRef,
    sourcesRef,
    symbolDetails,
    searchSources,
  ]);

  useEffect(() => {
    const term = searchTerm.trim();
    if (!term) {
      if (editMode && editSymbol) return;

      cancelCurrentSearch();
      lastTriggeredSearchRef.current = "";
      if (sourcesRef.current.length > 0) {
        publishSources([]);
      }
      return;
    }

    if (term === lastTriggeredSearchRef.current) return;

    if (searchTimerRef.current) window.clearTimeout(searchTimerRef.current);
    searchTimerRef.current = window.setTimeout(() => {
      lastTriggeredSearchRef.current = term;
      searchSources(term);
    }, SEARCH_DEBOUNCE_MS);

    return () => {
      if (searchTimerRef.current) window.clearTimeout(searchTimerRef.current);
    };
  }, [
    searchTerm,
    editMode,
    editSymbol,
    cancelCurrentSearch,
    lastTriggeredSearchRef,
    publishSources,
    searchSources,
    searchTimerRef,
    sourcesRef,
  ]);

  return {
    searchTerm,
    setSearchTerm,
    searching,
    searchSources,
    sourcesRef,
    refetchBuilderSources,
  };
}
