import { useCallback, useState } from "react";
import { toast } from "@/components/toast";
import type {
  ListingAssetType,
  RecentEvent,
  RwaMarketSessionTemplate,
  SourceItem,
  SymbolDetail,
  SymbolItem,
  TradingParamsForm,
} from "../../../../types";
import {
  useBrokerListingSubmit,
  useBrokerListingUpdateParams,
} from "../../../../services";
import type { RwaMarketSessionRow } from "../../../../services/types";
import {
  getTradingParamsApiErrorMessage,
  normalizeDisplaySymbolName,
  toIsoStringFromLocalInput,
  type SubmitMode,
} from "./shared";
import { type ListingStore } from "@/permissionless-listing/store/useListingStore";
import { useListingRefreshActions } from "@/permissionless-listing/hooks/useListingRefreshActions";
import { usePermissionlessListingNavigation } from "@/permissionless-listing/hooks/usePermissionlessListingNavigation";
import { useBrokerSymbolLogoUploader } from "./useBrokerSymbolLogoUpload";
import {
  buildNewSymbolItem,
  buildFinalNewSymbolDetail,
  buildRecentEvent,
  buildSubmitPayload,
  buildSymbolStoreKey,
  buildTradingSubmitInputs,
  buildTradingSubmitSources,
  buildTradingSymbolDetail,
  buildUpdateParamsPayload,
  getListingTimeLabel,
  isSameListingTime,
  mergeUpdatedTradingSymbolDetail,
  toLocalDateTimeInputValue,
} from "./submit.helpers";

type SubmitInputs = NonNullable<ReturnType<typeof buildTradingSubmitInputs>>;

type UseTradingParamsSubmitInput = {
  form: TradingParamsForm;
  selectedSources: SourceItem[];
  editMode: boolean;
  editSymbol: string | null;
  symbolDetails: Record<string, SymbolDetail>;
  listedSymbols: SymbolItem[];
  /** Base-filtered index sources catalog from store (contains source_symbol/source_id from API). */
  indexSourcesCatalog: ListingStore["indexSources"];
  brokerId?: string;
  updateSymbolDetail: (symbol: string, detail: SymbolDetail) => void;
  addEvent: (event: RecentEvent) => void;
  setSymbols: (symbols: SymbolItem[]) => void;
  validate: () => boolean;
  fundingCap: number;
  fundingFloor: number;
  quoteTick: number;
  baseTick: number;
  baseMin: number;
  baseMax: number;
  prettySymbol: string;
  /** Listing base for symbol_context / preview / submit (edit: from editSymbol). */
  listingBase: string;
  listingAssetType: ListingAssetType;
  rwaMarketSession: RwaMarketSessionTemplate | "";
  /** RWA market session rows from /v1/public/rwa/market_sessions. */
  rwaMarketSessions: RwaMarketSessionRow[];
  symbolIconFile: File | null;
  logoSymbolPreview: string;
  markSymbolIconUploaded: (logoUrl: string) => void;
  canEditDisplayName: boolean;
  isPretge: boolean;
};

export function useTradingParamsSubmit({
  form,
  selectedSources,
  editMode,
  editSymbol,
  symbolDetails,
  listedSymbols,
  indexSourcesCatalog,
  brokerId,
  updateSymbolDetail,
  addEvent,
  setSymbols,
  validate,
  fundingCap,
  fundingFloor,
  quoteTick,
  baseTick,
  baseMin,
  baseMax,
  prettySymbol,
  listingBase,
  listingAssetType,
  rwaMarketSession,
  rwaMarketSessions,
  symbolIconFile,
  logoSymbolPreview,
  markSymbolIconUploaded,
  canEditDisplayName,
  isPretge,
}: UseTradingParamsSubmitInput) {
  const [submitting, setSubmitting] = useState(false);
  const [submitModalOpen, setSubmitModalOpen] = useState(false);
  const [submitMode, setSubmitMode] = useState<SubmitMode | null>(null);
  const [submitSymbolLabel, setSubmitSymbolLabel] = useState<string>("");
  const [defaultListingDate, setDefaultListingDate] = useState<string>("");
  const [submitListing] = useBrokerListingSubmit();
  const [updateListingParams] = useBrokerListingUpdateParams();

  const { refreshListingSymbols } = useListingRefreshActions();
  const { uploadFile: uploadSymbolIconFile } = useBrokerSymbolLogoUploader();

  const { navigateToDashboard, navigateToSymbolDetail } =
    usePermissionlessListingNavigation();
  const displaySymbolName = normalizeDisplaySymbolName(
    form.display_symbol_name,
    listingBase
  );

  const buildSymbolDetail = useCallback(
    (
      submittedSources?: ReturnType<typeof buildTradingSubmitSources>
    ): SymbolDetail => {
      return buildTradingSymbolDetail({
        form,
        selectedSources,
        listingBase,
        listingAssetType,
        rwaMarketSession,
        rwaMarketSessions,
        fundingCap,
        fundingFloor,
        quoteTick,
        baseTick,
        baseMin,
        baseMax,
        isPretge,
        submittedSources,
      });
    },
    [
      form,
      selectedSources,
      listingBase,
      listingAssetType,
      rwaMarketSession,
      rwaMarketSessions,
      fundingCap,
      fundingFloor,
      quoteTick,
      baseTick,
      baseMin,
      baseMax,
      isPretge,
    ]
  );

  const buildSubmitInputs = useCallback(
    () => buildTradingSubmitInputs(form),
    [form]
  );

  const buildSubmitSources = useCallback(
    () =>
      buildTradingSubmitSources({
        selectedSources,
        indexSourcesCatalog,
        marketSession: rwaMarketSession,
      }),
    [indexSourcesCatalog, rwaMarketSession, selectedSources]
  );

  const uploadStagedSymbolIconIfNeeded = useCallback(async () => {
    if (!symbolIconFile) return true;
    if (!logoSymbolPreview.trim()) {
      toast.error(
        "Cannot upload symbol icon before submit because the preview symbol is empty."
      );
      return false;
    }

    try {
      const { logoUrl } = await uploadSymbolIconFile({
        symbolPreview: logoSymbolPreview,
        file: symbolIconFile,
      });
      markSymbolIconUploaded(logoUrl);
      return true;
    } catch (error) {
      toast.error(
        error instanceof Error
          ? error.message
          : "Symbol icon upload failed. Please try again."
      );
      return false;
    }
  }, [
    symbolIconFile,
    logoSymbolPreview,
    uploadSymbolIconFile,
    markSymbolIconUploaded,
  ]);

  const handleActiveEditSubmit = useCallback(
    async (input: {
      symbol: string;
      existing: SymbolDetail;
      submitInputs: SubmitInputs;
      listingTimeIso?: string;
      listingTimeLabel?: string | null;
      successEventMessage?: string;
      successToastMessage?: string;
    }): Promise<boolean> => {
      const submitSources = buildSubmitSources();
      const updatePayload = buildUpdateParamsPayload({
        symbol: input.symbol,
        params: input.submitInputs,
        sources: submitSources,
        listingAssetType,
        rwaMarketSession,
        isPretge,
        listingTime: input.listingTimeIso,
        displaySymbolName:
          canEditDisplayName && form.display_symbol_name.trim()
            ? displaySymbolName
            : undefined,
      });

      try {
        const iconUploaded = await uploadStagedSymbolIconIfNeeded();
        if (!iconUploaded) {
          setSubmitting(false);
          return false;
        }

        const res = await updateListingParams(updatePayload);
        if (!res.success) {
          throw res;
        }
        const updated = buildSymbolDetail(updatePayload.sources);
        const updatedForMerge = canEditDisplayName
          ? updated
          : {
              ...updated,
              params: {
                ...updated.params,
                display_symbol_name: input.existing.params.display_symbol_name,
              },
            };
        const merged = mergeUpdatedTradingSymbolDetail({
          existing: input.existing,
          updated: updatedForMerge,
          listingTime: input.listingTimeLabel,
        });
        updateSymbolDetail(input.symbol, merged);
        addEvent(
          buildRecentEvent(
            input.successEventMessage ??
              (input.listingTimeIso
                ? `Successfully updated trading parameters and listing schedule for ${prettySymbol}`
                : `Successfully updated trading parameters for ${prettySymbol}`)
          )
        );
        navigateToSymbolDetail(input.symbol);
        toast.success(
          input.successToastMessage ??
            (input.listingTimeIso
              ? `Trading parameters and listing schedule updated for ${prettySymbol}`
              : `Trading parameters updated for ${prettySymbol}`)
        );
        await refreshListingSymbols();
        return true;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
      } catch (error: any) {
        toast.error(getTradingParamsApiErrorMessage(error));
        return false;
      } finally {
        setSubmitting(false);
      }
    },
    [
      buildSubmitSources,
      listingAssetType,
      rwaMarketSession,
      isPretge,
      form.display_symbol_name,
      displaySymbolName,
      canEditDisplayName,
      uploadStagedSymbolIconIfNeeded,
      updateListingParams,
      buildSymbolDetail,
      updateSymbolDetail,
      addEvent,
      prettySymbol,
      navigateToSymbolDetail,
      refreshListingSymbols,
    ]
  );

  const submitNewListingFromModal = useCallback(
    async (input: {
      listingDate: string;
      listingTimeStr: string | null;
    }): Promise<boolean> => {
      const baseToken = listingBase.trim().toUpperCase();
      if (!baseToken) {
        toast.error("Please enter a base symbol in Step 1.");
        setSubmitting(false);
        return false;
      }

      try {
        const submitInputs = buildSubmitInputs();
        if (!submitInputs) {
          toast.error(
            "Invalid trading parameters. Please check the form inputs."
          );
          setSubmitting(false);
          return false;
        }

        const iconUploaded = await uploadStagedSymbolIconIfNeeded();
        if (!iconUploaded) {
          setSubmitting(false);
          return false;
        }

        const submitPayload = buildSubmitPayload({
          symbol: baseToken,
          listingTime: toIsoStringFromLocalInput(input.listingDate),
          listingAssetType,
          rwaMarketSession,
          isPretge,
          inputs: submitInputs,
          sources: buildSubmitSources(),
          displaySymbolName,
        });

        const res = await submitListing(submitPayload);
        if (!res?.success) {
          throw res;
        }
        const detail = buildSymbolDetail(submitPayload.sources);
        const symbolKey = buildSymbolStoreKey({
          symbolValue: detail.params.Symbol.value,
          brokerId,
          nowMs: Date.now(),
        });
        const finalDetail = buildFinalNewSymbolDetail({
          detail,
          listingTime: input.listingTimeStr,
        });

        const newSymbolItem = buildNewSymbolItem({
          symbolKey,
          baseToken,
          selectedSourceCount: selectedSources.length,
          isPretge: listingAssetType === "rwa" ? false : isPretge,
          displayName: displaySymbolName || baseToken,
        });

        setSymbols([...listedSymbols, newSymbolItem]);
        updateSymbolDetail(symbolKey, finalDetail);
        addEvent(buildRecentEvent(`New symbol listed: PERP_${baseToken}_USDC`));
        navigateToDashboard();
        toast.success(`PERP_${baseToken}_USDC has been submitted`);
        await refreshListingSymbols();
        return true;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
      } catch (error: any) {
        toast.error(getTradingParamsApiErrorMessage(error));
        setSubmitting(false);
        return false;
      }
    },
    [
      listingBase,
      buildSubmitInputs,
      uploadStagedSymbolIconIfNeeded,
      listingAssetType,
      rwaMarketSession,
      isPretge,
      displaySymbolName,
      buildSubmitSources,
      submitListing,
      buildSymbolDetail,
      brokerId,
      selectedSources.length,
      setSymbols,
      listedSymbols,
      updateSymbolDetail,
      addEvent,
      navigateToDashboard,
      refreshListingSymbols,
    ]
  );

  const onPrimarySubmitClick = useCallback(async () => {
    if (submitting) return;
    if (!validate()) return;

    const submitInputs = buildSubmitInputs();
    if (!submitInputs) {
      toast.error("Invalid trading parameters. Please check the form inputs.");
      return;
    }
    setSubmitting(true);

    if (editMode && editSymbol) {
      const existing = symbolDetails[editSymbol];
      if (!existing) {
        toast.error(
          "Unable to find existing symbol details. Please refresh and try again."
        );
        setSubmitting(false);
        return;
      }
      if (existing.status === "PENDING") {
        setSubmitMode({
          kind: "edit-pending",
          symbol: editSymbol,
          existing,
          submitInputs,
        });
        setSubmitSymbolLabel(existing.params.Symbol?.value ?? editSymbol);
        setDefaultListingDate(toLocalDateTimeInputValue(existing.listingTime));
        setSubmitModalOpen(true);
        setSubmitting(false);
        return;
      }
      await handleActiveEditSubmit({
        symbol: editSymbol,
        existing,
        submitInputs,
      });
      return;
    }

    const preview = buildSymbolDetail();
    setSubmitMode({ kind: "new" });
    setSubmitSymbolLabel(preview.params.Symbol.value);
    setDefaultListingDate("");
    setSubmitModalOpen(true);
    setSubmitting(false);
  }, [
    submitting,
    validate,
    buildSubmitInputs,
    editMode,
    editSymbol,
    symbolDetails,
    buildSymbolDetail,
    handleActiveEditSubmit,
  ]);

  const onSubmitFromModal = useCallback(
    async (listingDate: string) => {
      if (submitting) return false;
      if (!submitMode) return false;
      setSubmitting(true);

      try {
        const listingTimeStr = getListingTimeLabel(listingDate);

        if (submitMode.kind === "new") {
          const success = await submitNewListingFromModal({
            listingDate,
            listingTimeStr,
          });
          if (!success) return false;
        } else if (submitMode.kind === "edit-pending") {
          const listingTimeIso = toIsoStringFromLocalInput(listingDate);
          const listingTimeChanged = !isSameListingTime(
            listingTimeIso,
            submitMode.existing.listingTime
          );
          const success = await handleActiveEditSubmit({
            symbol: submitMode.symbol,
            existing: submitMode.existing,
            submitInputs: submitMode.submitInputs as SubmitInputs,
            listingTimeIso: listingTimeChanged ? listingTimeIso : undefined,
            listingTimeLabel: listingTimeChanged ? listingTimeStr : undefined,
          });
          if (!success) return false;
        }

        setSubmitting(false);
        setSubmitModalOpen(false);
        setSubmitMode(null);
      } catch (error) {
        // Keep the dialog open on unexpected errors, so users can retry.
        toast.error(getTradingParamsApiErrorMessage(error));
        setSubmitting(false);
        return false;
      }

      return true;
    },
    [submitMode, submitting, submitNewListingFromModal, handleActiveEditSubmit]
  );

  return {
    submitting,
    submitModalOpen,
    setSubmitModalOpen,
    submitSymbolLabel,
    defaultListingDate,
    onPrimarySubmitClick,
    onSubmitFromModal,
  };
}
