/** Max symbol slots per broker. */
export function getSymbolListingLimit(): number {
  return 50;
}

const SYMBOL_SLOT_USED_STATUSES: SymbolStatus[] = [
  "PENDING",
  "POST_ONLY",
  "ACTIVE",
  "REDUCE_ONLY",
];

export function isSymbolSlotUsed(status?: string | null): boolean {
  return SYMBOL_SLOT_USED_STATUSES.includes(status as SymbolStatus);
}

export function getSymbolSlotUsedCountFromListingStats(
  stats?: BrokerListingOverviewListingStats | null
): number {
  if (!stats) return 0;
  return stats.pending + stats.post_only + stats.active + stats.reduce_only;
}

