function getDefaultIfAccountMinRequired(): number {
  const env = getOrderlyEnv() as OrderlyEnv | "dev";

  const envToValue: Record<OrderlyEnv | "dev", number> = {
    dev: 50,
    qa: 50,
    staging: 100,
    prod: 25_000,
  };

  return envToValue[env] ?? envToValue.prod;
}

export function getIfRequired(riskSnapshot?: BrokerListingRiskSnapshotData) {
  return (
    riskSnapshot?.if_account?.min_required || getDefaultIfAccountMinRequired()
  );
}

export function getIfRequiredPerSymbol(
  riskSnapshot?: BrokerListingRiskSnapshotData
) {
  return (
    (riskSnapshot?.if_account?.min_required ||
      getDefaultIfAccountMinRequired()) /
    (riskSnapshot?.active_symbol_count || 1)
  );
}

export function getIfRequiredForNewSymbol(
  riskSnapshot?: BrokerListingRiskSnapshotData
) {
  return (
    getIfRequiredPerSymbol(riskSnapshot) *
    ((riskSnapshot?.active_symbol_count ?? 0) + 1)
  );
}

export function getTierRequired(tier?: string) {
  if (TIER_REQUIREMENT_WAIVED) return true;
  if (!tier) return false;
  return (Object.values(TierKey) as string[]).includes(tier);
}
