import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useBrokerInfo } from "@/components/provider/BrokerInfoProvider";
import { ListingSubStep } from "../../../types";
import { DEFAULT_TRADING_PARAMS_FORM } from "../../../constants";
import { useSelectListingStore } from "../../../store/useListingStore";
import {
  useCexPerpMetas,
  useFundingCapFloor,
  useTickAndLimits,
  useTradingParamsDerived,
  useTradingParamsForm,
  useTradingParamsImportAndCopy,
  useTradingParamsSubmit,
  useTradingParamsValidation,
} from "./hooks";
import {
  useGetBrokerListingSymbolContext,
  useRwaMarketSessions,
} from "@/permissionless-listing/services";
import { ListingAssetType } from "../../../types";
import type { SymbolStatus } from "../../../types";
import {
  applyRwaTradingLimits,
  buildListingLogoSymbolPreview,
  getAdjustedSourcePrices,
  getAveragePrice,
  getEffectiveListingBase,
  getFundingPeriodPendingState,
  getSelectedPriceSources,
  toRwaMarketSessionOptions,
} from "./hooks/derived.helpers";
import { useListingIndexSourcesData } from "../../../hooks/useListingIndexSourcesData";

export function useTradingParamsScript() {
  const { brokerId } = useBrokerInfo();
  const autoSelectedRwaMarketSessionRef = useRef<string | null>(null);
  const editDraftSyncKeyRef = useRef<string | null>(null);
  const skipInitialEditDraftSyncRef = useRef(false);
  const [endPretgeDialogOpen, setEndPretgeDialogOpen] = useState(false);
  const [endPretgeConfirmText, setEndPretgeConfirmText] = useState("");
  const {
    priceSources,
    editMode,
    editSymbol,
    currentListingBase,
    listingAssetType,
    symbolDetails,
    listedSymbols,
    listingStep,
    pretgeContextActive,
    isPretge,
    isPretgeUserSet,
    tradingParamsDraft,
    indexSources: storeIndexSources,
    updateSymbolDetail,
    addEvent,
    setSymbols,
    setListingStep,
    setPretgeState,
    setTradingParamsDraft,
  } = useSelectListingStore(s => ({
    priceSources: s.priceSources,
    editMode: s.editMode,
    editSymbol: s.editSymbol,
    currentListingBase: s.currentListingBase,
    listingAssetType: s.listingAssetType,
    symbolDetails: s.symbolDetails,
    listedSymbols: s.listedSymbols,
    updateSymbolDetail: s.updateSymbolDetail,
    addEvent: s.addEvent,
    setSymbols: s.setSymbols,
    setListingStep: s.setListingStep,
    listingStep: s.listingStep,
    pretgeContextActive: s.pretgeContextActive,
    isPretge: s.isPretge,
    isPretgeUserSet: s.isPretgeUserSet,
    tradingParamsDraft: s.tradingParamsDraft,
    indexSources: s.indexSources,
    setPretgeState: s.setPretgeState,
    setTradingParamsDraft: s.setTradingParamsDraft,
  }));
  const { indexSources: apiIndexSources } = useListingIndexSourcesData();
  const indexSources = storeIndexSources.length
    ? storeIndexSources
    : apiIndexSources;

  const selectedSources = useMemo(
    () => getSelectedPriceSources(priceSources),
    [priceSources]
  );

  const effectiveListingBase = useMemo(() => {
    return getEffectiveListingBase({
      editMode,
      editSymbol,
      currentListingBase,
    });
  }, [editMode, editSymbol, currentListingBase]);

  const { fundingPeriodPending, fundingPeriodEffectiveAt } = useMemo(() => {
    return getFundingPeriodPendingState({
      editMode,
      editSymbol,
      symbolDetails,
    });
  }, [editMode, editSymbol, symbolDetails]);

  useEffect(() => {
    const editDraftSyncKey = editMode && editSymbol ? editSymbol : null;
    if (editDraftSyncKeyRef.current === editDraftSyncKey) return;
    editDraftSyncKeyRef.current = editDraftSyncKey;
    skipInitialEditDraftSyncRef.current =
      Boolean(editDraftSyncKey) && !tradingParamsDraft;
  }, [editMode, editSymbol, tradingParamsDraft]);

  const currentEditStatus = useMemo<SymbolStatus | null>(() => {
    if (!editMode || !editSymbol) return null;
    return symbolDetails[editSymbol]?.status ?? null;
  }, [editMode, editSymbol, symbolDetails]);

  const displayNameEditable = useMemo(() => {
    if (!editMode) return true;
    return (
      currentEditStatus === "ACTIVE" ||
      currentEditStatus === "POST_ONLY" ||
      currentEditStatus === "REDUCE_ONLY"
    );
  }, [editMode, currentEditStatus]);

  const { data: symbolContext } = useGetBrokerListingSymbolContext({
    symbol:
      listingStep === ListingSubStep.TradingParams
        ? effectiveListingBase
        : undefined,
    is_pretge: listingAssetType === ListingAssetType.Rwa ? false : isPretge,
  });
  const {
    data: rwaMarketSessions,
    error: rwaMarketSessionsError,
    isLoading: rwaMarketSessionsLoading,
  } = useRwaMarketSessions({ revalidateOnFocus: false });

  const logoSymbolPreview = useMemo(() => {
    return buildListingLogoSymbolPreview({
      selectedSources,
      effectiveListingBase,
      brokerId,
    });
  }, [effectiveListingBase, selectedSources, brokerId]);

  const {
    form,
    setForm,
    errors,
    setErrors,
    warnings,
    setWarnings,
    updateField,
    symbolIconFile,
    hasStagedSymbolIcon,
    symbolIconDisplayUrl,
    stageSymbolIcon,
    removeSymbolIcon,
    markSymbolIconUploaded,
    crop,
    onSymbolIconCropConfirm,
  } = useTradingParamsForm({
    params: tradingParamsDraft ?? {
      ...DEFAULT_TRADING_PARAMS_FORM,
      listing_asset_type: listingAssetType ?? ListingAssetType.Crypto,
    },
    preferInitialParams: Boolean(tradingParamsDraft),
    editMode,
    editSymbol,
    symbolDetails,
    symbolContext,
    logoSymbolPreview,
  });

  useEffect(() => {
    if (skipInitialEditDraftSyncRef.current) {
      skipInitialEditDraftSyncRef.current = false;
      return;
    }
    setTradingParamsDraft(form);
  }, [form, setTradingParamsDraft]);

  useEffect(() => {
    autoSelectedRwaMarketSessionRef.current = null;
  }, [editMode, effectiveListingBase, listingAssetType]);

  useEffect(() => {
    if (listingAssetType !== ListingAssetType.Rwa) return;
    if (editMode) return;
    if (!rwaMarketSessions || rwaMarketSessions.length === 0) return;
    const recommendedSession = symbolContext?.market_session?.trim() || "";
    const recommendedSessionExists =
      recommendedSession.length > 0 &&
      rwaMarketSessions.some(
        session => session.market_session === recommendedSession
      );
    const nextSession = recommendedSessionExists
      ? recommendedSession
      : rwaMarketSessions[0].market_session;

    setForm(prev => {
      const autoSelected = autoSelectedRwaMarketSessionRef.current;
      if (prev.rwa_market_session && prev.rwa_market_session !== autoSelected) {
        return prev;
      }
      if (prev.rwa_market_session === nextSession) {
        autoSelectedRwaMarketSessionRef.current = nextSession;
        return prev;
      }
      autoSelectedRwaMarketSessionRef.current = nextSession;
      return {
        ...prev,
        rwa_market_session: nextSession,
      };
    });
  }, [listingAssetType, editMode, rwaMarketSessions, setForm, symbolContext]);

  const updateTradingParamField = useCallback(
    (field: Parameters<typeof updateField>[0], value: string) => {
      if (field === "rwa_market_session") {
        autoSelectedRwaMarketSessionRef.current = null;
      }
      updateField(field, value);
    },
    [updateField]
  );

  useEffect(() => {
    if (listingStep !== ListingSubStep.TradingParams || editMode) return;
    const params = symbolContext?.params;
    if (!params) return;

    setForm(prev => {
      const next = { ...prev };
      const applyEnumDefault = (field: "max_leverage" | "funding_period") => {
        const ctxParam = params[field];
        if (!ctxParam || ctxParam.type !== "enum") return;
        const normalize = (value: unknown) =>
          field === "max_leverage"
            ? String(value).replace(/x$/i, "")
            : String(value);
        const values = ctxParam.values.map(normalize);
        if (values.includes(next[field])) return;
        const suggested =
          ctxParam.suggested !== undefined ? normalize(ctxParam.suggested) : "";
        next[field] = values.includes(suggested)
          ? suggested
          : (values[0] ?? "");
      };
      const applyIntegerDefault = (
        field: "global_max_oi" | "max_notional_user"
      ) => {
        const ctxParam = params[field];
        if (!ctxParam || ctxParam.type !== "integer") return;
        const current = Number(next[field]);
        if (
          Number.isFinite(current) &&
          current >= ctxParam.min &&
          current <= ctxParam.max
        ) {
          return;
        }
        const suggested = Number(ctxParam.suggested);
        next[field] = String(
          Number.isFinite(suggested) ? suggested : ctxParam.min
        );
      };

      applyEnumDefault("max_leverage");
      applyEnumDefault("funding_period");
      applyIntegerDefault("global_max_oi");
      applyIntegerDefault("max_notional_user");

      if (
        next.max_leverage === prev.max_leverage &&
        next.funding_period === prev.funding_period &&
        next.global_max_oi === prev.global_max_oi &&
        next.max_notional_user === prev.max_notional_user
      ) {
        return prev;
      }

      return next;
    });
  }, [editMode, listingStep, setForm, symbolContext?.params]);

  useEffect(() => {
    if (listingAssetType === ListingAssetType.Rwa) {
      setPretgeState({
        pretgeContextActive: false,
        isPretge: false,
        isPretgeUserSet: true,
      });
    }
  }, [listingAssetType, setPretgeState]);

  const showEndPretgePhasePanel =
    editMode &&
    isPretge &&
    listingAssetType !== ListingAssetType.Rwa &&
    pretgeContextActive;

  const { leverage, imr, mmr, prettySymbol } = useTradingParamsDerived({
    form,
    editSymbol,
  });

  const {
    cexFundingParamsLoading,
    cexTickParamsLoading,
    cexMetasForTick,
    cexFundingMetas,
    cexStepSizeCandidates,
  } = useCexPerpMetas({
    priceSources,
    baseSymbol: effectiveListingBase,
  });

  const { quoteTick, baseTick, baseMin, baseMax } = useTickAndLimits({
    symbolContext,
    selectedSources,
    globalMaxOi: form.global_max_oi,
    baseSymbol: effectiveListingBase,
    cexTickParamsLoading,
    cexMetasForTick,
    cexStepSizeCandidates,
  });

  const { fundingCap, fundingFloor } = useFundingCapFloor({
    fundingPeriod: form.funding_period,
    cexFundingMetas,
  });

  const selectedAdjustedPrices = useMemo(
    () =>
      getAdjustedSourcePrices(selectedSources, {
        normalizeFxDirection:
          form.listing_asset_type === ListingAssetType.Rwa &&
          form.rwa_market_session?.trim().toUpperCase() === "FX",
        listingBase: effectiveListingBase,
      }),
    [
      effectiveListingBase,
      form.listing_asset_type,
      form.rwa_market_session,
      selectedSources,
    ]
  );

  const avgSelectedPrice = useMemo(
    () => getAveragePrice(selectedAdjustedPrices),
    [selectedAdjustedPrices]
  );

  const {
    quoteTick: effectiveQuoteTick,
    baseTick: effectiveBaseTick,
    baseMin: effectiveBaseMin,
    baseMax: effectiveBaseMax,
  } = applyRwaTradingLimits({
    listingAssetType: form.listing_asset_type,
    avgSelectedPrice,
    quoteTick,
    baseTick,
    baseMin,
    baseMax,
  });

  const { validateFields, validateForSubmit } = useTradingParamsValidation({
    form,
    selectedSources,
    setErrors,
    setWarnings,
    symbolContext,
    canEditDisplayName: displayNameEditable,
  });

  const {
    submitting,
    submitModalOpen,
    setSubmitModalOpen,
    submitSymbolLabel,
    defaultListingDate,
    onPrimarySubmitClick,
    onSubmitFromModal,
  } = useTradingParamsSubmit({
    form,
    selectedSources,
    editMode,
    editSymbol,
    symbolDetails,
    listedSymbols,
    indexSourcesCatalog: indexSources,
    brokerId,
    updateSymbolDetail,
    addEvent,
    setSymbols,
    validate: validateForSubmit,
    fundingCap,
    fundingFloor,
    quoteTick: effectiveQuoteTick,
    baseTick: effectiveBaseTick,
    baseMin: effectiveBaseMin,
    baseMax: effectiveBaseMax,
    prettySymbol,
    listingBase: effectiveListingBase,
    listingAssetType: form.listing_asset_type,
    rwaMarketSession: form.rwa_market_session,
    rwaMarketSessions: rwaMarketSessions ?? [],
    symbolIconFile,
    logoSymbolPreview,
    markSymbolIconUploaded,
    canEditDisplayName: displayNameEditable,
    isPretge,
  });

  const endPretgeConfirmSymbol = prettySymbol;
  const canConfirmEndPretgePhase =
    endPretgeConfirmText === endPretgeConfirmSymbol && !submitting;

  const onConfirmEndPretgePhase = useCallback(async () => {
    if (!canConfirmEndPretgePhase) return;
    setPretgeState({
      isPretge: false,
      isPretgeUserSet: true,
    });
    setEndPretgeDialogOpen(false);
  }, [canConfirmEndPretgePhase, setPretgeState]);

  useEffect(() => {
    if (!endPretgeDialogOpen) {
      setEndPretgeConfirmText("");
    }
  }, [endPretgeDialogOpen]);

  const onBack = useCallback(() => {
    setListingStep(ListingSubStep.PriceSources);
  }, [setListingStep]);

  const {
    openImportModal,
    importModalOpen,
    setImportModalOpen,
    importJSON,
    copyForLLM,
  } = useTradingParamsImportAndCopy({
    setForm,
    canEditDisplayName: displayNameEditable,
  });

  return {
    form,
    updateField: updateTradingParamField,
    errors,
    warnings,
    leverage,
    imr,
    mmr,
    fundingCap,
    fundingFloor,
    quoteTick: effectiveQuoteTick,
    baseTick: effectiveBaseTick,
    baseMin: effectiveBaseMin,
    baseMax: effectiveBaseMax,
    selectedSources,
    submitting,
    onPrimarySubmitClick,
    onSubmitFromModal,
    submitModalOpen,
    setSubmitModalOpen,
    submitSymbolLabel,
    defaultListingDate,
    brokerId,
    onBack,
    onValidateFields: validateFields,
    openImportModal,
    importModalOpen,
    setImportModalOpen,
    importJSON,
    copyForLLM,
    editMode,
    prettySymbol,
    effectiveListingBase,
    cexFundingParamsLoading,
    cexTickParamsLoading,
    fundingPeriodPending,
    fundingPeriodEffectiveAt,
    displayNameEditable,
    symbolContext,
    listingAssetType: form.listing_asset_type,
    isPretge,
    showEndPretgePhasePanel,
    endPretgeDialogOpen,
    setEndPretgeDialogOpen,
    endPretgeConfirmText,
    setEndPretgeConfirmText,
    endPretgeConfirmSymbol,
    canConfirmEndPretgePhase,
    onConfirmEndPretgePhase,
    isPretgeUserSet,
    rwaMarketSession: form.rwa_market_session,
    rwaMarketSessionOptions: toRwaMarketSessionOptions(rwaMarketSessions ?? []),
    rwaMarketSessionError: rwaMarketSessionsError
      ? "Failed to load market sessions."
      : undefined,
    rwaMarketSessionLoading: rwaMarketSessionsLoading,
    hasStagedSymbolIcon,
    symbolIconDisplayUrl,
    stageSymbolIcon,
    removeSymbolIcon,
    crop,
    onSymbolIconCropConfirm,
  };
}
