import { cn } from "@/utils/css";
import type { RwaMarketSessionRow } from "../../../services/types";
import type { TradingParamsForm } from "../../../types";
import {
  PLSelect,
  PLSelectContent,
  PLSelectGroup,
  PLSelectItem,
  PLSelectLabel,
  PLSelectTrigger,
} from "../../../components";
import { TemplateInfoBlock } from "./ParamFormFields";

/** API row plus Select control fields (`value` mirrors `market_session`). */
export type RwaMarketSessionOption = RwaMarketSessionRow & {
  value: string;
  label: string;
};

type MarketGroup = {
  label: string;
  items: string[];
};

const SESSION_GROUPS: MarketGroup[] = [
  {
    label: "US Markets",
    items: ["US_STOCK", "US_STOCK_EXT", "US_FUTURES"],
  },
  {
    label: "Asia Stock Markets",
    items: ["HK_STOCK", "KR_STOCK", "CN_STOCK"],
  },
  {
    label: "FX",
    items: ["FX"],
  },
];

const FX_COPY: Record<
  string,
  { currency: string; fullName: string; showCnhWarning?: boolean }
> = {
  HK_STOCK: {
    currency: "HKD",
    fullName: "Hong Kong Dollar",
  },
  KR_STOCK: {
    currency: "KRW",
    fullName: "Korean Won",
  },
  CN_STOCK: {
    currency: "CNH",
    fullName: "offshore RMB",
    showCnhWarning: true,
  },
};

function getGroupedOptions(options: RwaMarketSessionOption[]) {
  const byValue = new Map(options.map(item => [item.value, item]));
  return SESSION_GROUPS.map(group => ({
    ...group,
    items: group.items
      .map(value => byValue.get(value))
      .filter((item): item is RwaMarketSessionOption => Boolean(item)),
  })).filter(group => group.items.length > 0);
}

function InfoBanner({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex items-start gap-2.5 rounded-lg border border-primary-light/20 bg-primary/[0.08] px-3.5 py-3 text-2xs leading-[1.6] text-base-contrast-98">
      <div className="mt-0.5 shrink-0 text-primary-light">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
          <circle cx="8" cy="8" r="7" stroke="currentColor" strokeWidth="1.4" />
          <rect
            x="7.5"
            y="7"
            width="1"
            height="4"
            rx="0.5"
            fill="currentColor"
          />
          <rect
            x="7.5"
            y="4.5"
            width="1"
            height="1"
            rx="0.5"
            fill="currentColor"
          />
        </svg>
      </div>
      <div>{children}</div>
    </div>
  );
}

function WarningBanner({ children }: { children: React.ReactNode }) {
  return (
    <div className="flex items-start gap-2.5 rounded-lg border border-warning/[0.22] bg-warning/10 px-3.5 py-3 text-2xs leading-[1.6] text-base-contrast-98">
      <div className="mt-0.5 shrink-0 text-warning">
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
          <path
            d="M8 2L14.5 13.5H1.5L8 2Z"
            stroke="currentColor"
            strokeWidth="1.4"
            strokeLinejoin="round"
          />
          <rect
            x="7.5"
            y="7"
            width="1"
            height="3.5"
            rx="0.5"
            fill="currentColor"
          />
          <rect
            x="7.5"
            y="11.5"
            width="1"
            height="1"
            rx="0.5"
            fill="currentColor"
          />
        </svg>
      </div>
      <div>{children}</div>
    </div>
  );
}

export function RwaMarketSessionSection({
  value,
  options,
  error,
  loading,
  onChange,
}: {
  value: TradingParamsForm["rwa_market_session"];
  options: RwaMarketSessionOption[];
  error?: string;
  loading: boolean;
  onChange: (value: string) => void;
}) {
  const sessionInfo = options.find(item => item.value === value) ?? null;
  const groupedOptions = getGroupedOptions(options);
  const fxCopy = value ? FX_COPY[value] : undefined;

  return (
    <div className="mt-1 border-t border-base-contrast-8 pt-6">
      <div className="mb-4">
        <div className="text-xs font-medium text-base-contrast-98">
          RWA symbol
        </div>
        <div className="mt-1 text-3xs text-base-contrast-50">
          Configure market hours and holiday schedules for this real-world
          asset.
        </div>
      </div>

      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-1">
          <span className="text-xs font-medium text-base-contrast-98">
            Market session
          </span>
          <span className="text-xs font-medium text-primary-light">*</span>
        </div>
        <PLSelect
          value={value || undefined}
          onValueChange={onChange}
          disabled={loading || Boolean(error)}
        >
          <PLSelectTrigger
            className={cn(
              "min-h-[40px] w-full",
              error && "border-danger enabled:hover:border-danger"
            )}
          >
            <span
              className={cn(
                "block truncate text-left",
                !sessionInfo && "text-base-contrast-50"
              )}
            >
              {sessionInfo?.label ?? "Select market template..."}
            </span>
          </PLSelectTrigger>
          <PLSelectContent className="max-h-[360px] w-[var(--radix-select-trigger-width)] max-w-[var(--radix-select-trigger-width)] p-2">
            {groupedOptions.map((group, groupIndex) => (
              <PLSelectGroup key={group.label}>
                <PLSelectLabel
                  className={cn(
                    "px-3 pb-1.5 pt-2 text-4xs font-semibold uppercase tracking-[0.06em] text-primary-light",
                    groupIndex > 0 &&
                      "mt-1 border-t border-base-contrast-8 pt-3"
                  )}
                >
                  {group.label}
                </PLSelectLabel>
                {group.items.map(item => (
                  <PLSelectItem
                    key={item.value}
                    value={item.value}
                    textValue={item.label}
                    className="items-start rounded-lg px-3 py-2.5 [&>span:last-child]:block [&>span:last-child]:max-w-full [&>span:last-child]:whitespace-normal"
                  >
                    <div className="flex w-full min-w-0 flex-col gap-0.5 whitespace-normal">
                      <span className="block whitespace-normal break-words text-2xs font-medium text-base-contrast-98">
                        {item.label}
                      </span>
                      <span className="block whitespace-normal break-words text-4xs leading-5 text-base-contrast-50">
                        {item.name?.trim() ? item.name : item.market_session} ·{" "}
                        {item.trading_hours}
                      </span>
                    </div>
                  </PLSelectItem>
                ))}
              </PLSelectGroup>
            ))}
          </PLSelectContent>
        </PLSelect>
        {error ? (
          <span className="text-3xs text-danger">{error}</span>
        ) : (
          <span className="text-3xs text-base-contrast-36">
            {loading
              ? "Loading available market sessions..."
              : "Choose the template that matches the underlying market."}
          </span>
        )}
      </div>

      <div className="mt-3 grid grid-cols-1 gap-3 rounded-lg bg-base-300 px-4 py-3 sm:grid-cols-3">
        <TemplateInfoBlock
          label="Market"
          value={sessionInfo?.name?.trim() ? sessionInfo.name : "—"}
        />
        <TemplateInfoBlock
          label="Timezone"
          value={sessionInfo?.timezone ?? "—"}
        />
        <TemplateInfoBlock
          label="Schedule"
          value={sessionInfo?.trading_hours ?? "—"}
        />
      </div>
      {fxCopy ? (
        <div className="mt-3 flex flex-col gap-2">
          <InfoBanner>
            Please ensure your price feed is quoted in{" "}
            <strong className="font-medium text-base-contrast-98">
              {fxCopy.currency} ({fxCopy.fullName})
            </strong>
            . Orderly will automatically convert prices to USD using a
            platform-managed FX rate.
          </InfoBanner>
          {fxCopy.showCnhWarning ? (
            <WarningBanner>
              Note: Orderly uses the{" "}
              <strong className="font-medium text-base-contrast-98">
                CNH/USD
              </strong>{" "}
              (offshore RMB) rate. If your feed is in{" "}
              <strong className="font-medium text-base-contrast-98">CNY</strong>{" "}
              (onshore RMB), the CNH/CNY basis (typically &lt; 0.5%) is treated
              as a known constant deviation.
            </WarningBanner>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
