import type { ReactNode } from "react";
import { Button } from "@/components/button";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/dialog";
import { CheckIcon, ExternalLinkIcon } from "../CustomOracleIcons";
import {
  CUSTOM_ORACLE_BUILDER_ORACLE_DOC_URL,
  CUSTOM_ORACLE_BYOK_ORACLE_DOC_URL,
} from "../../docsLinks";

interface OnboardingModalProps {
  open: boolean;
  onClose: () => void;
  onSelectTab: (tab: "builder" | "byok") => void;
}

interface OnboardingCardProps {
  tab: "builder" | "byok";
  title: string;
  description: string;
  docUrl: string;
  benefits: string[];
  icon: ReactNode;
  onSelectTab: (tab: "builder" | "byok") => void;
}

function OnboardingCard({
  tab,
  title,
  description,
  docUrl,
  benefits,
  icon,
  onSelectTab,
}: OnboardingCardProps) {
  const selectTab = () => onSelectTab(tab);

  return (
    <div
      role="button"
      tabIndex={0}
      className="flex cursor-pointer gap-4 rounded-xl border border-base-contrast-8 bg-base-200 p-4 text-left transition hover:-translate-y-px hover:border-primary hover:bg-primary/10 focus-visible:-translate-y-px focus-visible:border-primary focus-visible:bg-primary/10 focus-visible:outline-none"
      onClick={selectTab}
      onKeyDown={event => {
        if (event.key !== "Enter" && event.key !== " ") return;
        event.preventDefault();
        selectTab();
      }}
    >
      <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-[10px] bg-primary/10 text-primary-light">
        {icon}
      </div>
      <div className="flex-1">
        <div className="text-xs font-semibold leading-[1.2] text-base-contrast-98">
          {title}
        </div>
        <p className="mt-1 text-3xs leading-normal text-base-contrast-54">
          {description}
        </p>
        <div className="mt-2 space-y-1 text-3xs leading-normal text-base-contrast-54">
          {benefits.map(benefit => (
            <div key={benefit} className="flex items-start gap-2">
              <CheckIcon className="mt-1 h-3 w-3 text-success" />
              <span>{benefit}</span>
            </div>
          ))}
        </div>
        <button
          type="button"
          className="mt-2 inline-flex items-center gap-1 text-3xs leading-[1.2] text-primary-light hover:underline"
          onClick={event => {
            event.stopPropagation();
            window.open(docUrl, "_blank", "noreferrer");
          }}
        >
          Learn more
          <ExternalLinkIcon className="h-3 w-3" />
        </button>
      </div>
    </div>
  );
}

export function OnboardingModal({
  open,
  onClose,
  onSelectTab,
}: OnboardingModalProps) {
  return (
    <Dialog
      open={open}
      onOpenChange={nextOpen => {
        if (!nextOpen) onClose();
      }}
    >
      <DialogContent className="max-w-[600px]">
        <DialogHeader className="h-auto flex-col items-stretch gap-2 border-b-0 px-6 pt-6 pb-0">
          <DialogTitle className="text-lg font-medium leading-[1.2] text-base-contrast-98">
            Getting started
          </DialogTitle>
          <DialogDescription className="text-xs leading-normal text-base-contrast-50">
            There are two ways to provide prices for your assets.
          </DialogDescription>
        </DialogHeader>
        <DialogBody className="space-y-3 px-6 pt-5 pb-0">
          <OnboardingCard
            tab="builder"
            title="Builder oracle"
            description="A WebSocket endpoint where you push your own index price. You can aggregate from multiple oracles behind the scenes."
            docUrl={CUSTOM_ORACLE_BUILDER_ORACLE_DOC_URL}
            benefits={[
              "Full control over pricing logic and data quality",
              "List any asset, not limited by provider coverage",
            ]}
            onSelectTab={onSelectTab}
            icon={
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z" />
                <path d="m3.3 7 8.7 5 8.7-5" />
                <path d="M12 22V12" />
              </svg>
            }
          />
          <OnboardingCard
            tab="byok"
            title="Bring your own key"
            description="Connect to Pyth or Stork using your API key. Orderly pulls prices for you, so this is the fastest way to get started."
            docUrl={CUSTOM_ORACLE_BYOK_ORACLE_DOC_URL}
            benefits={[
              "Zero infrastructure, just provide your API key",
              "Instant setup and automatic price updates",
            ]}
            onSelectTab={onSelectTab}
            icon={
              <svg
                width="20"
                height="20"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden="true"
              >
                <circle cx="7.5" cy="15.5" r="5.5" />
                <path d="m21 2-9.6 9.6" />
                <path d="m15.5 7.5 3 3L22 7l-3-3" />
              </svg>
            }
          />
        </DialogBody>
        <DialogFooter className="justify-end px-6 pb-6 pt-6">
          <Button onClick={onClose}>Got it</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
