"use client";

import { useCallback } from "react";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/dialog";
import { Button } from "@/components/button";
import { cn } from "@/utils/css";
import type { UseSymbolIconCropReturn } from "./hooks/useSymbolIconCrop";

interface SymbolIconCropModalProps {
  crop: UseSymbolIconCropReturn;
  onConfirm: (blob: Blob) => void;
}

export function SymbolIconCropModal({
  crop,
  onConfirm,
}: SymbolIconCropModalProps) {
  const {
    open,
    zoom,
    zoomMin,
    canvasRef,
    canvasPointerHandlers,
    setZoom,
    cancelCrop,
    confirmCrop,
  } = crop;

  const handleConfirm = useCallback(() => {
    void confirmCrop()
      .then(onConfirm)
      .catch(() => {
        // confirmCrop may reject if canvas is unavailable; silently close.
      });
  }, [confirmCrop, onConfirm]);

  return (
    <Dialog
      open={open}
      onOpenChange={nextOpen => {
        if (!nextOpen) cancelCrop();
      }}
    >
      <DialogContent className="max-w-[520px]">
        <DialogHeader>
          <DialogTitle className="text-base">Crop symbol icon</DialogTitle>
        </DialogHeader>
        <DialogBody className="flex flex-row flex-wrap items-start gap-5">
          {/* Left: circular crop preview */}
          <div
            className={cn(
              "relative shrink-0 overflow-hidden rounded-full border border-base-contrast-12",
              "bg-[#07020f]",
              "w-[min(280px,calc(95vw-80px))] aspect-square"
            )}
          >
            <canvas
              ref={canvasRef}
              width={280}
              height={280}
              className={cn(
                "block w-full h-full touch-none rounded-full",
                zoom > 1 / Math.SQRT2
                  ? "cursor-grab active:cursor-grabbing"
                  : "cursor-default"
              )}
              onPointerDown={canvasPointerHandlers.onPointerDown}
              onPointerMove={canvasPointerHandlers.onPointerMove}
              onPointerUp={canvasPointerHandlers.onPointerUp}
              onPointerCancel={canvasPointerHandlers.onPointerCancel}
              onPointerLeave={canvasPointerHandlers.onPointerLeave}
            />
          </div>

          {/* Right: horizontal zoom slider */}
          <div className="flex-1 min-w-0 flex flex-col gap-2">
            <span className="text-xs font-medium text-base-contrast-98">
              Zoom
            </span>
            <input
              type="range"
              min={zoomMin}
              max={3}
              step={0.01}
              value={zoom}
              onChange={e => setZoom(parseFloat(e.target.value))}
              className="w-full accent-primary cursor-pointer"
              aria-label="Zoom"
            />
          </div>
        </DialogBody>
        <DialogFooter className="justify-end gap-2 border-t border-base-contrast-8">
          <Button
            variant="outline"
            color="primary"
            size="md"
            onClick={cancelCrop}
          >
            Cancel
          </Button>
          <Button size="md" onClick={handleConfirm}>
            Confirm
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
