"use client";

import { useCallback, useRef, useState } from "react";

const ICON_MAX_BYTES = 1024 * 1024; // 1 MB
const ICON_OUTPUT_SIZE = 64; // output: 64×64 px
const ICON_CANVAS_SIZE = 280; // preview canvas size
const ICON_ACCEPTED_TYPES = ["image/png", "image/jpeg"];
const ZOOM_MIN = 0.25;
const ZOOM_MAX = 3;

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function validateIconFile(file: File): string | null {
  if (!file) return "No file selected.";
  const lowerName = (file.name || "").toLowerCase();
  const isSupportedType =
    ICON_ACCEPTED_TYPES.includes(file.type) || /\.(png|jpe?g)$/.test(lowerName);
  if (!isSupportedType) return "File must be PNG or JPG.";
  if (file.size > ICON_MAX_BYTES) return "File must be ≤ 1 MB.";
  return null;
}

function readImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Could not read the file."));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("Failed to load image."));
      img.onload = () => resolve(img);
      img.src = reader.result as string;
    };
    reader.readAsDataURL(file);
  });
}

interface CropState {
  img: HTMLImageElement;
  /** User-facing zoom: 1 = cover the canvas, <1 = shrink toward contain, >1 = zoom in. */
  zoom: number;
  /** The base scale at which the image exactly covers the canvas (zoom=1). */
  coverScale: number;
  /** The scale at which the entire image fits inside the canvas (min zoom). */
  containScale: number;
  offsetX: number;
  offsetY: number;
  dragging: boolean;
  lastX: number;
  lastY: number;
}

/** Actual pixel-scale = coverScale × zoom. */
function effectiveScale(state: CropState): number {
  return state.coverScale * state.zoom;
}

function constrainOffsets(state: CropState) {
  const scale = effectiveScale(state);
  const drawW = state.img.naturalWidth * scale;
  const drawH = state.img.naturalHeight * scale;
  if (drawW >= ICON_CANVAS_SIZE) {
    const maxX = (drawW - ICON_CANVAS_SIZE) / 2;
    state.offsetX = clamp(state.offsetX, -maxX, maxX);
  } else {
    state.offsetX = 0;
  }
  if (drawH >= ICON_CANVAS_SIZE) {
    const maxY = (drawH - ICON_CANVAS_SIZE) / 2;
    state.offsetY = clamp(state.offsetY, -maxY, maxY);
  } else {
    state.offsetY = 0;
  }
}

function getDrawArgs(
  state: CropState,
  size: number
): { drawX: number; drawY: number; drawW: number; drawH: number } | null {
  if (!state.img) return null;
  const coverForSize = Math.max(
    size / state.img.naturalWidth,
    size / state.img.naturalHeight
  );
  const scale = coverForSize * state.zoom;
  const drawW = state.img.naturalWidth * scale;
  const drawH = state.img.naturalHeight * scale;
  const offsetScale = size / ICON_CANVAS_SIZE;
  const offsetX = state.offsetX * offsetScale;
  const offsetY = state.offsetY * offsetScale;
  return {
    drawX: (size - drawW) / 2 + offsetX,
    drawY: (size - drawH) / 2 + offsetY,
    drawW,
    drawH,
  };
}

function renderCanvas(canvas: HTMLCanvasElement, state: CropState) {
  constrainOffsets(state);
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, ICON_CANVAS_SIZE, ICON_CANVAS_SIZE);
  ctx.fillStyle = "#07020f";
  ctx.fillRect(0, 0, ICON_CANVAS_SIZE, ICON_CANVAS_SIZE);
  const args = getDrawArgs(state, ICON_CANVAS_SIZE);
  if (!args) return;
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = "high";
  ctx.drawImage(state.img, args.drawX, args.drawY, args.drawW, args.drawH);
}

function exportCroppedBlob(state: CropState): Promise<Blob> {
  return new Promise((resolve, reject) => {
    constrainOffsets(state);
    const output = document.createElement("canvas");
    output.width = ICON_OUTPUT_SIZE;
    output.height = ICON_OUTPUT_SIZE;
    const ctx = output.getContext("2d");
    if (!ctx) {
      reject(new Error("Canvas context unavailable."));
      return;
    }
    ctx.clearRect(0, 0, ICON_OUTPUT_SIZE, ICON_OUTPUT_SIZE);
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = "high";
    const args = getDrawArgs(state, ICON_OUTPUT_SIZE);
    if (args) {
      ctx.drawImage(state.img, args.drawX, args.drawY, args.drawW, args.drawH);
    }
    output.toBlob(blob => {
      if (blob) resolve(blob);
      else reject(new Error("Failed to export image."));
    }, "image/png");
  });
}

export interface UseSymbolIconCropReturn {
  /** Whether the crop modal is open. */
  open: boolean;
  /** Current zoom value (zoomMin-ZOOM_MAX). */
  zoom: number;
  /** Minimum zoom for the current image (depends on image size). */
  zoomMin: number;
  /** Open the crop modal with the given file. Rejects on validation error. */
  openCrop: (file: File) => Promise<void>;
  /** Confirm crop and return the 64×64 PNG Blob. */
  confirmCrop: () => Promise<Blob>;
  /** Cancel and close the modal. */
  cancelCrop: () => void;
  /** Set zoom value (clamped to zoomMin-ZOOM_MAX). */
  setZoom: (value: number) => void;
  /** Ref for the canvas element. */
  canvasRef: React.RefObject<HTMLCanvasElement | null>;
  /** Pointer event handlers for canvas drag. */
  canvasPointerHandlers: {
    onPointerDown: (e: React.PointerEvent<HTMLCanvasElement>) => void;
    onPointerMove: (e: React.PointerEvent<HTMLCanvasElement>) => void;
    onPointerUp: () => void;
    onPointerCancel: () => void;
    onPointerLeave: () => void;
  };
}

export function useSymbolIconCrop(): UseSymbolIconCropReturn {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const cropStateRef = useRef<CropState | null>(null);
  const [open, setOpen] = useState(false);
  const [zoom, setZoomState] = useState(1);
  const [zoomMin, setZoomMin] = useState(1);

  const reRender = useCallback(() => {
    const canvas = canvasRef.current;
    const state = cropStateRef.current;
    if (!canvas || !state) return;
    renderCanvas(canvas, state);
  }, []);

  const openCrop = useCallback(async (file: File) => {
    const err = validateIconFile(file);
    if (err) throw new Error(err);
    const img = await readImage(file);
    const coverScale = Math.max(
      ICON_CANVAS_SIZE / img.naturalWidth,
      ICON_CANVAS_SIZE / img.naturalHeight
    );
    const containScale = Math.min(
      ICON_CANVAS_SIZE / img.naturalWidth,
      ICON_CANVAS_SIZE / img.naturalHeight
    );
    const effectiveZoomMin = Math.max(containScale / coverScale, ZOOM_MIN);
    const state: CropState = {
      img,
      zoom: 1,
      coverScale,
      containScale,
      offsetX: 0,
      offsetY: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
    };
    cropStateRef.current = state;
    setZoomState(1);
    setZoomMin(effectiveZoomMin);
    setOpen(true);
    requestAnimationFrame(() => {
      const canvas = canvasRef.current;
      if (canvas) renderCanvas(canvas, state);
    });
  }, []);

  const confirmCrop = useCallback(async (): Promise<Blob> => {
    const state = cropStateRef.current;
    if (!state) throw new Error("No image to crop.");
    const blob = await exportCroppedBlob(state);
    setOpen(false);
    cropStateRef.current = null;
    return blob;
  }, []);

  const cancelCrop = useCallback(() => {
    setOpen(false);
    cropStateRef.current = null;
  }, []);

  const setZoom = useCallback(
    (value: number) => {
      const state = cropStateRef.current;
      const min = state
        ? Math.max(state.containScale / state.coverScale, ZOOM_MIN)
        : ZOOM_MIN;
      const clamped = clamp(value, min, ZOOM_MAX);
      setZoomState(clamped);
      if (state) {
        state.zoom = clamped;
        reRender();
      }
    },
    [reRender]
  );

  const getCanvasPointer = useCallback(
    (e: React.PointerEvent<HTMLCanvasElement>) => {
      const canvas = canvasRef.current;
      if (!canvas) return { x: 0, y: 0 };
      const rect = canvas.getBoundingClientRect();
      return {
        x: (e.clientX - rect.left) * (ICON_CANVAS_SIZE / rect.width),
        y: (e.clientY - rect.top) * (ICON_CANVAS_SIZE / rect.height),
      };
    },
    []
  );

  const canvasPointerHandlers = {
    onPointerDown: useCallback(
      (e: React.PointerEvent<HTMLCanvasElement>) => {
        const state = cropStateRef.current;
        if (!state) return;
        e.preventDefault();
        e.currentTarget.setPointerCapture(e.pointerId);
        const point = getCanvasPointer(e);
        state.dragging = true;
        state.lastX = point.x;
        state.lastY = point.y;
      },
      [getCanvasPointer]
    ),
    onPointerMove: useCallback(
      (e: React.PointerEvent<HTMLCanvasElement>) => {
        const state = cropStateRef.current;
        if (!state || !state.dragging) return;
        e.preventDefault();
        const point = getCanvasPointer(e);
        state.offsetX += point.x - state.lastX;
        state.offsetY += point.y - state.lastY;
        state.lastX = point.x;
        state.lastY = point.y;
        reRender();
      },
      [getCanvasPointer, reRender]
    ),
    onPointerUp: useCallback(() => {
      const state = cropStateRef.current;
      if (state) state.dragging = false;
    }, []),
    onPointerCancel: useCallback(() => {
      const state = cropStateRef.current;
      if (state) state.dragging = false;
    }, []),
    onPointerLeave: useCallback(() => {
      const state = cropStateRef.current;
      if (state) state.dragging = false;
    }, []),
  };

  return {
    open,
    zoom,
    zoomMin,
    openCrop,
    confirmCrop,
    cancelCrop,
    setZoom,
    canvasRef,
    canvasPointerHandlers,
  };
}
