"use client";

import { FC, useCallback } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogBody,
  DialogFooter,
} from "@/components/dialog";
import { Button } from "@/components/button";

interface ImportParamsModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onChooseFile: () => void;
}

const JSON_EXAMPLE = `{
  "max_leverage": 10,
  "global_max_oi": 1000000,
  "max_notional_user": 200000,
  "funding_period": "8h",
  "std_liquidation_fee": 0.015,
  "claim_IF_discount": 0.0075
}`;

export const ImportParamsModal: FC<ImportParamsModalProps> = ({
  open,
  onOpenChange,
  onChooseFile,
}) => {
  const handleChooseFile = useCallback(() => {
    onChooseFile();
    onOpenChange(false);
  }, [onChooseFile, onOpenChange]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-[520px]">
        <DialogHeader>
          <DialogTitle>Import parameters</DialogTitle>
        </DialogHeader>

        <DialogBody className="space-y-4">
          <div className="space-y-1.5">
            <span className="text-2xs font-medium text-base-contrast-98">
              Supported format
            </span>
            <span className="text-2xs text-base-contrast-50 leading-normal block">
              JSON file
            </span>
          </div>
          <pre className="m-0 p-4 bg-base-400 border border-base-contrast-8 rounded-lg text-2xs text-base-contrast-98 leading-[1.55] overflow-auto font-mono">
            {JSON_EXAMPLE}
          </pre>
        </DialogBody>

        <DialogFooter className="justify-end gap-3 border-t border-t-base-contrast-8">
          <Button
            variant="outline"
            color="primary"
            onClick={() => onOpenChange(false)}
          >
            Cancel
          </Button>
          <Button onClick={handleChooseFile}>Choose JSON file</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
