import { IndexSourceType } from "../types";

type SourceLike = {
  type?: IndexSourceType | string | null;
  source?: string | null;
  sourceId?: string | null;
  source_id?: string | null;
};

export const PRETGE_ORACLE_LABEL = "Pre-TGE Oracle";
export const PRETGE_ORACLE_SOURCE_PREFIX = "ORACLE_pretge_";

function normalizePretgeToken(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
}

export function isPretgeOracleType(
  type: IndexSourceType | string | null | undefined
): boolean {
  if (!type) return false;
  const normalized = normalizePretgeToken(String(type));
  return (
    normalized === IndexSourceType.PretgeOracle ||
    normalized === "pre_tge_oracle" ||
    normalized === "pretgeoracle"
  );
}

export function isPretgeOracleSource(source: SourceLike): boolean {
  const sourceId = source.sourceId ?? source.source_id ?? source.source ?? "";
  return (
    isPretgeOracleType(source.type) ||
    String(sourceId)
      .toUpperCase()
      .startsWith(PRETGE_ORACLE_SOURCE_PREFIX.toUpperCase())
  );
}

export function normalizePretgeSourceType<T extends SourceLike>(source: T): T {
  if (!isPretgeOracleSource(source)) return source;
  return {
    ...source,
    type: IndexSourceType.PretgeOracle,
  };
}
